/* Networking Basics. Original teaching scenarios; documentation addresses only. */
(() => {
const source=(title,url)=>({title,url,checked:'2026-10-04'});
const refs={lan:source('Cisco: local area networks','https://www.cisco.com/site/us/en/learn/topics/networking/what-is-a-lan-local-area-network.html'),wlan:source('Cisco: wireless LANs','https://www.cisco.com/site/us/en/learn/topics/networking/what-is-a-wireless-lan.html'),radio:source('Cisco: high-density wireless design (principles; older platform examples)','https://www.cisco.com/c/en/us/td/docs/wireless/controller/technotes/8-7/b_wireless_high_client_density_design_guide.html'),eth:source('RFC 894: IPv4 over Ethernet (historical standard; see errata)','https://www.rfc-editor.org/rfc/rfc894'),arp:source('RFC 826: address resolution','https://www.rfc-editor.org/rfc/rfc826'),mac:source('RFC 7042: IEEE 802 identifiers and documentation usage','https://www.rfc-editor.org/rfc/rfc7042'),v4:source('RFC 791: IPv4','https://www.rfc-editor.org/rfc/rfc791'),v6:source('RFC 8200: IPv6','https://www.rfc-editor.org/rfc/rfc8200'),mtu:source('RFC 1191: IPv4 Path MTU Discovery','https://www.rfc-editor.org/rfc/rfc1191'),plp:source('RFC 4821: packetization-layer PMTU discovery','https://www.rfc-editor.org/rfc/rfc4821'),tcp:source('RFC 6349: TCP throughput testing framework','https://www.rfc-editor.org/rfc/rfc6349'),duplex:source('Cisco: Ethernet negotiation and legacy duplex mismatch','https://www.cisco.com/c/en/us/support/docs/lan-switching/ethernet/10561-3.html'),link:source('iproute2: ip link manual','https://man7.org/linux/man-pages/man8/ip-link.8.html'),route:source('iproute2: ip route manual','https://man7.org/linux/man-pages/man8/ip-route.8.html'),neigh:source('iproute2: ip neighbour manual','https://man7.org/linux/man-pages/man8/ip-neighbour.8.html'),ping:source('iputils: ping manual','https://man7.org/linux/man-pages/man8/ping.8.html'),tool:source('ethtool manual','https://man7.org/linux/man-pages/man8/ethtool.8.html'),win:source('Microsoft: Get-NetAdapter','https://learn.microsoft.com/en-us/powershell/module/netadapter/get-netadapter?view=windowsserver2025-ps')};
const q=(difficulty,testedConcept,question,answer,explanation,options)=>({difficulty,testedConcept,question,answer,explanation,type:options?'multiple-choice':'short-answer',...(options?{options}:{})});
const cmd=(code,explanation,expected,platform='Ubuntu 24.04 / Bash + iproute2')=>({code,explanation,expected,platform,filename:platform.startsWith('Windows')?'PowerShell':'bash'});
const lesson=(i,body)=>({id:`s0-g2-t${i}`,batch:'03',level:'Beginner → Production',minutes:30,prerequisites:['s0-g0-t4','s0-g1-t3'],related:[],...body});
const lessons=[lesson(0,{
title:'LAN',subtitle:'Find the local forwarding boundary before blaming the Internet.',
definition:'A local area network connects devices within a limited site such as an office or campus. It commonly uses switched Ethernet and wireless access. One physical site can contain many logical LAN segments separated by VLANs and routing.',
purpose:'Local connectivity lets users reach printers, applications and gateways without sending every exchange through a distant provider. Separating local segments also limits the reach of broadcasts and allows different access policies. A working Internet connection and a working local service are distinct outcomes.',
mental:'Picture rooms joined by internal corridors and exits to other buildings. Switches connect endpoints inside a logical room; a router provides a controlled path between IP networks. Physical distance alone does not draw the rooms: VLANs can separate adjacent desks or span several switches.',
components:['Endpoint interfaces carry link addresses and an IP configuration.','Access switches learn source MAC addresses within VLAN context and forward frames.','VLAN membership defines logical Layer 2 boundaries; cabling alone does not define membership.','A default gateway routes traffic to other networks; DHCP and DNS support clients but perform different jobs.'],
mechanism:['An application selects a destination IP, often after a DNS lookup. The host consults its routing table to choose an interface and next hop. A route that treats the destination as directly connected leads to local neighbor resolution; a gateway route resolves the gateway instead.','For IPv4 over Ethernet, ARP can resolve the chosen next-hop IP to a MAC address. The outgoing frame contains the next-hop destination MAC while the IP packet contains the final IP destination. IPv6 uses Neighbor Discovery rather than ARP.','A switch learns the arriving source MAC on its ingress port within the VLAN. A known unicast destination is forwarded toward its learned port. Unknown unicast and broadcast traffic may be flooded to eligible ports in that VLAN, excluding ingress; policy and loop-prevention state still apply.','A router terminates the incoming link frame and makes an IP forwarding decision. Separate VLANs normally need this Layer 3 path to communicate. Merely attaching two devices to the same chassis does not guarantee that they share a segment or an allowed policy path.'],
flow:[['Choose the route','The endpoint chooses local delivery or a gateway using its actual routing table.'],['Resolve next hop','ARP for IPv4, or Neighbor Discovery for IPv6, identifies a reachable neighbor on the local link.'],['Forward the frame','The switch uses VLAN and destination MAC; it does not resolve application names.'],['Cross the boundary','Off-link traffic reaches a router; local traffic need not pass through the default gateway.']],
comparison:[['LAN','Site-local connectivity','Can contain several routed segments.'],['VLAN','Logical Layer 2 segment','Broadcast reach is bounded by membership and forwarding policy.'],['IP subnet','Address-prefix boundary','Usually aligned with a VLAN in simple designs, but not the same object.'],['WAN','Connectivity between sites or provider edges','Adds path and administrative dependencies.']],
example:'A laptop at 192.0.2.10/24 reaches a printer at 192.0.2.20 without using its default gateway in this simple topology. A server at 198.51.100.20 is off-link and uses gateway 192.0.2.1. These reserved documentation addresses are a diagram, not a suggestion to configure your real adapter.',
commands:[cmd('ip -br address\nip route show','Inspect assigned addresses and routes without changing them.','Look for the selected interface, prefix and default route. A link marked UP does not prove a valid address or gateway.'),cmd('ip neigh show','Inspect cached neighbor mappings.','REACHABLE, STALE, INCOMPLETE and FAILED describe different neighbor states. An empty cache on an idle machine is not proof of a fault; WSL shows its virtual network context.')],
configuration:'For a new segment, document its purpose, VLAN, IP prefix, gateway, address-assignment method and allowed flows. Validate switch-port membership and endpoint configuration together. Persistent host configuration may belong to NetworkManager, systemd-networkd or another manager. Do not mix ad hoc ip commands with managed configuration without a plan. Save the previous state and ensure console access before a real connectivity change.',
ports:'LAN, Ethernet and ARP have no TCP/UDP port of their own. DNS, DHCP and application ports are services carried over the network, not definitions of a LAN.',
production:'An office separates employees, guests, printers and management into documented segments. Routing and firewall policy permit required service flows between them. Monitor gateway availability, interface errors, address-pool capacity and client experience separately; one green switch light cannot summarize all four.',
troubleshooting:[['Symptom','A relocated desktop cannot reach its printer, but its Ethernet link is up.'],['Hypotheses','Wrong VLAN, stale IP configuration, address conflict, host policy or printer failure.'],['Test','Compare the desktop address/prefix, access-port VLAN and neighbor state with the intended design and a known-good client.'],['Observation','Synthetic evidence: the desk port is in VLAN 30; the desktop still has the VLAN 20 address configuration.'],['Conclusion / next test','Link establishment succeeded, but logical membership and addressing disagree. Verify the intended port assignment before changing anything.'],['Fix and verify','In an authorized change, correct the assignment and renew/reapply managed addressing. Retest local neighbor resolution, printer service and permitted off-link access. Confirm forbidden guest access remains blocked.']],
security:'Local does not mean trusted. Segment guests and administration, authenticate access where supported, and restrict management services. MAC allowlists are weak identity controls because link addresses can change or be copied. Discovery and packet captures can expose device names and user activity; collect only necessary evidence.',
performance:'A local bottleneck can be an oversubscribed uplink, a broadcast storm, a busy endpoint or wireless airtime. Compare interface counters over a measured interval, not raw lifetime totals. Keep normal broadcast domains manageable and eliminate accidental Layer 2 loops with a reviewed topology and loop protection.',
mistakes:['Treating a VLAN number as an IP subnet mask.','Assuming every same-building flow crosses the default gateway.','Calling a DNS failure a broken cable without checking IP reachability.'],interactive:'journey',
lab:{objective:'Explain local versus routed delivery and identify a VLAN/address mismatch.',requirements:'Browser packet journey and an observation notebook; Linux inspection is optional. No switch access is required.',topology:['Laptop / VLAN 20','Access switch','Router','Server / VLAN 30'],steps:['Use the packet journey below the flow sections: step from client through router to server; record both IP and MAC destinations at each stage.','Compare local printer 192.0.2.20 with remote server 198.51.100.20 for a 192.0.2.10/24 client. Predict whether a gateway is needed.','Inspect local addresses/routes if using Linux; label virtual interfaces and avoid publishing addresses.','Diagnose the synthetic relocated-desktop scenario above. State what each observation proves and what remains untested.','Write a correction and verification plan without executing a switch or address change.'],verification:'The remote packet keeps its destination IP while next-hop MAC addresses change across the router. The local printer needs no gateway in the stated simple topology. The diagnosis distinguishes physical link from logical membership.',troubleshooting:'If the host uses VPNs, policy routing or WSL, its actual route may differ from the teaching diagram. Record that difference rather than forcing the host to match it.',challenge:'Two devices share a VLAN but use different IP prefixes. Explain why common Layer 2 membership alone does not guarantee normal direct IP communication.',cleanup:'Reset the journey. Observation only; no host or switch configuration was modified.'},
quick:[q('Beginner','Boundary','Does a LAN require Internet access?','No.','Local services can work while the upstream WAN is unavailable.'),q('Intermediate','Next hop','For an off-link server, whose MAC is in the first Ethernet destination field?','The local next-hop router MAC.','The final server IP remains in the packet.'),q('Intermediate','VLAN','Does one switch imply one broadcast domain?','No.','VLANs can separate forwarding domains on one switch.')],
exams:[q('Beginner','Scope','Which best describes a LAN?','Connectivity within a limited site.','LAN describes scope, not a mandatory speed or a particular application.',['Any encrypted tunnel','Connectivity within a limited site.','Only Internet access','A DNS record']),q('Intermediate','Local flow','In the stated /24 example, does 192.0.2.10 need its default gateway to reach 192.0.2.20?','Normally no; the connected route selects direct neighbor delivery.','This assumes matching VLAN/link reachability and no overriding routes or isolation.'),q('Troubleshooting','VLAN','Link is up after a desk move, but ARP for the intended gateway fails. What evidence is most useful next?','Compare access VLAN and endpoint address/prefix with the intended segment.','A physical carrier does not establish logical segment membership.'),q('Intermediate','Learning','Which arriving field does a switch normally learn into its forwarding database?','Source MAC address.','Destination MAC is used for forwarding; source MAC identifies where the sender was observed.',['DNS name','Destination TCP port','Source MAC address.','IP default route']),q('Advanced','Flooding','An unknown unicast is flooded. Does that mean every VLAN receives it?','No; ordinary flooding is bounded to eligible ports in the relevant VLAN.','VLAN membership and forwarding policy constrain the scope.'),q('Design','Segmentation','Why separate guest and management traffic?','To establish distinct access boundaries and enforce limited allowed flows.','A label alone is insufficient; routing and policy must enforce the design.'),q('Troubleshooting','DNS','A local service works by IP but not name. What should be investigated before replacing a cable?','Name resolution and name-dependent application behavior.','Successful IP service access is evidence that some network path is already working.'),q('Intermediate','ARP','Does ARP translate a hostname into an IP address?','No; it resolves an IPv4 next-hop address to a link address on the local network.','DNS and ARP solve different mapping problems.'),q('Advanced','Evidence','Why is an empty neighbor cache not conclusive evidence of failure?','The host may be idle or entries may have expired; no relevant resolution may have been attempted.','Interpret cache state in the context of an observed flow.'),q('Design','Acceptance','What should a segmentation change verify beyond successful permitted access?','That forbidden flows remain blocked and management/recovery access remains available.','Positive and negative tests establish the intended boundary.')],
glossary:{LAN:'Local area network serving a limited site.',VLAN:'Logical Layer 2 forwarding segment.','Default gateway':'Router used when the selected default route applies.','Broadcast domain':'Scope in which a Layer 2 broadcast can be forwarded.'},related:['s0-g2-t1','s0-g2-t4','s0-g2-t6'],sources:[refs.lan,refs.arp,refs.link,refs.route,refs.neigh]
}),lesson(1,{
title:'WAN',subtitle:'Separate the service path from the circuit that carries it.',
definition:'A wide area network connects separated sites or networks across a broader geographic and administrative span. It may use provider services, Internet access and tunnels. WAN is a scope and design concept, not one protocol or a guarantee of encryption.',
purpose:'Organizations need branches, data centers, cloud services and remote users to exchange traffic beyond a single local site. WAN design makes reachability, performance, cost and recovery explicit where the organization may control only part of the path.',
mental:'Think of shipping between buildings: local loading docks connect to transport providers, and a private shipment can travel inside a shared carrier. The analogy stops at routing, which selects paths per forwarding policy and may use different return paths rather than one fixed road in both directions.',
components:['Customer edge: the organization’s router/firewall and LAN-facing routes.','Provider handoff: physical/logical access with an agreed rate, encapsulation and support boundary.','Underlay: the reachable transport network that carries traffic.','Overlay: optional tunnels or logical paths built across that underlay, with their own state and overhead.','Remote edge and return routing: the destination also needs a permitted way back.'],
mechanism:['A branch host sends remote traffic to its selected gateway. The edge applies forwarding and security policy, then chooses a reachable next hop or overlay. The existence of a default route is only one piece of that decision.','A tunnel can wrap the original packet in additional headers. The underlay routes the outer packet; the far edge decapsulates it and forwards the inner packet. Encapsulation consumes space and may lower the effective MTU available to the application.','The provider transports traffic across infrastructure the customer does not fully observe. A handoff can remain electrically up during an upstream outage, a routing failure or a provider policer drop. Service health therefore needs measurements beyond link state.','The response follows its own routing and policy decisions. Asymmetric paths are possible. Stateful firewalls, source validation, tunnel selectors and missing return routes can break one direction even when the outbound edge appears correct.'],
flow:[['Branch route','A host and edge select the remote destination path.'],['Encapsulate if needed','An overlay adds headers; encryption exists only when the chosen protocol and policy provide it.'],['Provider transport','The underlay forwards to the remote endpoint within its capacity and failure domain.'],['Remote delivery and reply','The remote edge decapsulates, applies policy and delivers; return reachability is verified separately.']],
comparison:[['Internet access','Reachability through shared public routing','Does not imply a private or encrypted application path.'],['Private provider service','Contracted separation/connectivity','Verify security properties; private does not automatically mean encrypted.'],['VPN overlay','Logical path carried by another network','Depends on underlay reachability and adds overhead.'],['Dual circuits','Two access services','Resilience depends on actual physical and administrative diversity.']],
example:'A branch has a 1 Gb/s LAN uplink but a 100 Mb/s WAN service. A backup stream and interactive traffic share that WAN. The LAN port rate does not increase the contracted WAN rate, and a second circuit in the same underground duct may not survive the same excavation.',
commands:[cmd('ip route show\nip route get 198.51.100.20','Read the routing table and ask the kernel which route it would choose for a documentation destination.','route get performs a local route lookup; it is not a reachability test and sends no probe to that destination. VPN/policy context may change results.'),cmd('ip -s link show','Read interface counters at the customer endpoint.','Take two timestamped observations to measure deltas. Clean local counters cannot prove the provider path or remote service is healthy.')],
configuration:'Record circuit identifiers, demarcation points, shaping rates, addressing, routes, tunnel endpoints and ownership. Define path health checks that represent the service, not merely the directly connected gateway. Before failover changes, retain console access and a known-good route/policy snapshot. Validate both directions and restore the previous policy if the planned acceptance checks fail.',
ports:'WAN itself has no TCP/UDP port. An overlay may use IPsec, GRE or another encapsulation, each with its own protocol identifiers and policy requirements. GRE is an IP protocol, not a TCP port; application ports remain separate.',
production:'A retail branch sends payment traffic to an approved service and backups to a central site. The design gives interactive traffic bounded delay under load, documents backup completion expectations and tests loss of each access path. Provider escalation includes time, circuit, affected destinations, packet-size behavior and directional evidence.',
troubleshooting:[['Symptom','Branch users reach local services but not the remote application.'],['Hypotheses','Provider reachability, tunnel state, route selection, remote return route or application policy.'],['Test','Compare the local route decision, tunnel/edge counters and a remote-side observation during the same bounded request.'],['Observation','Synthetic record: the remote edge receives requests, but its return route points to a retired branch prefix.'],['Conclusion / next test','The request path works to the remote edge; test the return routing/policy before replacing the access circuit.'],['Fix and verify','Correct the approved return route, then verify complete transactions in both directions and failover behavior. Retain the previous route for rollback.']],
security:'Authenticate tunnel peers and protect keys when using an encrypted overlay. Restrict edge management and avoid assuming carrier separation meets confidentiality requirements. Scope reachability to business flows. A failover path needs equivalent security policy; an emergency Internet circuit should not silently bypass controls.',
performance:'End-to-end throughput is constrained by bottleneck capacity, competing traffic, transport windows, loss and endpoints. Long distance contributes propagation delay. Tunnels add packet overhead. Define latency, loss and availability at measurement points and distinguish a contract from measured application behavior.',
mistakes:['Treating a tunnel as independent of its underlay.','Calling two circuits diverse without checking shared ducts, power and provider dependencies.','Ignoring the return path because requests leave the branch.'],
lab:{objective:'Diagnose a one-way WAN failure and evaluate a resilience claim from synthetic evidence.',requirements:'Notebook and the supplied scenario; optional read-only Linux route lookup.',topology:['Branch client','Customer edge','Provider / optional tunnel','Remote edge','Application'],steps:['Draw the request and response paths as separate arrows. Mark the two administrative handoffs.','Use the example 1 Gb/s LAN and 100 Mb/s WAN to identify the capacity constraint for a single branch transfer.','Read the synthetic failure record in the diagnosis and identify which path has evidence of success.','Write the missing return-route hypothesis and a remote-side test that could disprove it.','Compare two proposed backup circuits: same duct versus separate entry/provider. List common dependencies still needing verification.'],verification:'The answer identifies the WAN bottleneck, separates underlay/overlay and request/reply, and refuses to equate two circuits with proven diversity.',troubleshooting:'A local route lookup only predicts the local decision. Do not turn that into a claim that a tunnel, provider or application was tested.',challenge:'A small transaction succeeds while a large transfer stalls after tunneling. Explain why MTU evidence belongs in the investigation.',cleanup:'No live tunnel or route changed. Keep the topology and evidence worksheet.'},
quick:[q('Beginner','Encryption','Does WAN automatically mean encrypted?','No.','Security properties depend on the service and protocols.'),q('Intermediate','Underlay','Can an overlay work when it has no viable underlay path?','No.','Its outer packets still require transport.'),q('Intermediate','Return path','Does observing requests remotely prove complete reachability?','No.','Responses need their own valid routing and policy.')],
exams:[q('Beginner','Scope','What defines WAN in this lesson?','Connectivity across separated sites/networks.','It is not a single cable type or tunnel protocol.',['A particular TCP port','Connectivity across separated sites/networks.','All links above 1 Gb/s','Every VLAN']),q('Intermediate','Capacity','A 1 Gb/s LAN feeds a 100 Mb/s WAN. What is the ideal upper link-rate bound for a WAN transfer before overhead?','100 Mb/s.','The narrower path constrains the transfer.',['1 Gb/s','100 Mb/s.','1.1 Gb/s','Unlimited']),q('Troubleshooting','Direction','Remote captures show arriving requests and replies leaving the wrong interface. Which area deserves attention?','Remote return routing and policy.','Arrival demonstrates only part of the path.'),q('Design','Diversity','Why might two provider circuits fail together?','They may share ducts, power, equipment or upstream dependencies.','Provider names alone do not prove independent failure domains.'),q('Intermediate','Encapsulation','Why can a tunnel expose an MTU problem?','Additional headers consume the underlay packet budget.','The inner packet may no longer fit even when it fits its local interface MTU.'),q('Advanced','State','Can an edge interface be up while the WAN service is unusable?','Yes; upstream routing, policy or provider failures can occur beyond the handoff.','Physical link state is narrower evidence than end-to-end service health.'),q('Design','Health checks','Why test an application transaction during failover?','Gateway reachability can survive while DNS, policy, routing or the application path fails.','A useful acceptance test represents the actual service.'),q('Intermediate','Privacy','Does a private carrier service necessarily encrypt customer payloads?','No; verify its actual confidentiality properties.','Logical separation and cryptographic protection are different controls.'),q('Troubleshooting','Route lookup','What does ip route get prove?','The kernel route decision for that lookup context, not destination availability.','It is a local prediction rather than a successful packet exchange.'),q('Advanced','SLA','Why record measurement endpoints when comparing latency figures?','Different endpoints and paths include different access, queueing and processing delays.','A provider-core metric cannot be assumed equal to user transaction delay.')],
glossary:{WAN:'Wide area network connecting separated networks.',Underlay:'Transport network carrying an overlay.','Overlay':'Logical connectivity built over another network.','Demarcation':'Boundary of operational responsibility for a service.'},related:['s0-g2-t0','s0-g2-t7','s0-g2-t8','s0-g2-t9'],sources:[refs.route,refs.link,refs.tcp,refs.mtu]
}),lesson(2,{
title:'WLAN',subtitle:'A strong signal is only one part of a working wireless service.',
definition:'A wireless LAN connects clients by radio, usually using IEEE 802.11 Wi-Fi. Access points bridge or tunnel client traffic into the wider network. Association with an access point is distinct from obtaining an IP address, resolving names and reaching an application.',
purpose:'Wireless access supports mobility and devices without a cable at every location. Its shared radio environment requires deliberate coverage, capacity and security design. Adding access points or increasing transmit power does not automatically increase usable capacity.',
mental:'Imagine a meeting in which participants must coordinate opportunities to speak. A distant speaker may need more time and repetition. The analogy is simplified: modern Wi-Fi can schedule multiple users and links, so it is not a literal rule that only one device anywhere can transmit at a time.',
components:['Client radio/driver and supported capabilities affect association, rates and roaming.','SSID identifies a wireless network name; BSSID identifies a particular basic service set.','Access-point radios operate on channels and compete with other users of the spectrum.','Authentication and key establishment control access to protected WLANs.','Distribution path: AP uplink, VLAN/tunnel, gateway, DHCP and DNS complete the service chain.'],
mechanism:['A client discovers candidate networks and chooses an AP according to its implementation and policy. Identical SSID names can appear on many radios. A name alone neither authenticates the network nor tells you the client’s current AP.','The station performs applicable authentication/association exchanges and, for a protected network, the required security/key establishment. Enterprise deployments may depend on an identity service and client certificate validation. The exact sequence depends on the security mode.','Data uses radio resources under contention and scheduling rules. Rate adaptation, retransmissions, interference and management overhead consume airtime. The displayed PHY rate is not the application throughput. AP Ethernet forwarding or tunneling then connects the client to its segment.','The client still needs valid IP configuration, neighbor reachability and application access. During movement, roaming may change the BSSID while the SSID remains the same. Voice performance depends on interruption and path behavior, not simply the number of signal bars.'],
flow:[['Discover','Identify candidate SSIDs/BSSIDs and available channels.'],['Join securely','Associate and complete required authentication/key establishment.'],['Use airtime','Transmit with contention/scheduling, acknowledgments and possible retries.'],['Reach services','Obtain usable IP configuration and traverse the AP distribution path to applications.']],
comparison:[['SSID','Network name','Several AP radios may advertise the same name.'],['BSSID','Basic service set identifier','Useful when correlating a client with a specific AP/radio.'],['Signal strength','Received power observation','Does not describe noise, airtime load or backend health alone.'],['PHY rate','Radio transmission rate for a link condition','Application goodput is lower and variable.']],
example:'A meeting room shows a strong signal with 40 clients but slow video calls. High channel utilization and retries point toward contention/interference or client conditions. If clients associate but receive no address, the AP-to-DHCP/VLAN path is a different investigation even with identical signal bars.',
commands:[cmd('netsh wlan show interfaces','Inspect Windows WLAN connection state, SSID/BSSID, radio/channel and displayed rates where supported.','No wireless interface may exist. Some Windows configurations require location permission for detailed Wi-Fi information; do not bypass a denied policy. Rates and signal are observations, not guaranteed throughput.','Windows 11 / PowerShell or Command Prompt'),cmd('ip -br address\nip route show','Inspect the client IP layer after association in a Linux environment.','WSL commonly sees virtual Ethernet, not the host Wi-Fi radio. These commands cannot establish channel occupancy or RF quality.')],
configuration:'Plan coverage and capacity from the client population, building and regulatory domain. Select supported security modes, certificate validation and sensible channel/power policies. Stage SSID/VLAN changes with a test client and a rollback profile. Avoid maximizing channel width or power without survey evidence; both can increase interference or reduce channel reuse.',
ports:'802.11 association and radio MAC exchanges are not TCP/UDP services. Enterprise authentication and controller tunnels introduce separate backend protocols. Their ports depend on the deployment; a client may associate successfully while those dependencies or DHCP are unavailable.',
production:'A campus distinguishes employee, guest and device access, with client-specific policy and monitored authentication. Engineers correlate user symptoms with AP/radio, channel, time, retries, utilization and backend logs. A controlled roaming walk test checks interruption as well as final connectivity; a desktop speed test cannot replace it.',
troubleshooting:[['Symptom','Clients in one room have strong signal but poor calls.'],['Hypotheses','High airtime demand, interference, retries, overloaded uplink or application delay.'],['Test','Correlate radio utilization/retry trends with client count and a wired baseline at the same time.'],['Observation','Synthetic evidence: wired calls are healthy, the affected channel is busy, retries rise during meetings and neighboring channels are less loaded.'],['Conclusion / next test','Evidence narrows the problem to the wireless access domain; survey co-channel activity and client capabilities before changing power.'],['Fix and verify','Apply a reviewed channel/capacity adjustment during a change window. Repeat the room workload and roaming checks; compare retries, delay and call quality, then roll back if the boundary conditions worsen.']],
security:'Validate enterprise authentication server certificates and avoid treating an SSID as identity. Use appropriate supported WPA security and isolate guest/device access. Protect AP administration and review rogue-network reports. Wireless captures contain nearby users’ metadata; inspection should be limited to authorized devices and scope.',
performance:'Airtime is finite. Slow transmissions, retries and management frames reduce resources available for useful payload. Wider channels can raise peak rates but reduce reuse in crowded spectrum. RF design must consider uplink and downlink: a powerful AP may be heard by a client that cannot transmit back reliably.',
mistakes:['Equating signal bars with usable capacity.','Treating a repeated SSID as proof of the same AP.','Expecting WSL virtual NIC output to describe the host radio.'],
lab:{objective:'Separate radio, association and IP-service symptoms using a wireless evidence worksheet.',requirements:'Notebook and supplied synthetic observations. A Windows Wi-Fi interface is optional; do not change location or security policy for this lab.',topology:['Client radio','AP / BSSID','AP uplink and VLAN','Gateway / DHCP / application'],steps:['List the four observations you need: association/BSSID, radio conditions, IP configuration and application result.','Optionally run the Windows command and redact SSID/BSSID before sharing. Record unsupported/permission-denied output as a limitation.','Case A: associated, strong signal, no usable IP address. Mark the next checks for DHCP and segment assignment.','Case B: valid address, wired baseline healthy, channel busy and retries high. Mark the next RF investigation.','Propose one targeted change per case and a before/after verification, keeping both changes as a tabletop plan.'],verification:'The worksheet assigns different tests to missing IP configuration and airtime contention; it does not infer radio quality from virtual Ethernet or signal alone.',troubleshooting:'If no WLAN adapter is available, use the supplied cases. Absence of a radio in WSL is expected in many installations and is not a WLAN failure.',challenge:'Why can increasing AP power make client experience worse or fail to fix an uplink problem?',cleanup:'Read-only inspection and tabletop work only. No SSID, channel, certificate or adapter setting changed.'},
quick:[q('Beginner','Identity','Are SSID and BSSID interchangeable?','No.','One SSID can be advertised by multiple BSSIDs.'),q('Intermediate','Airtime','Does a high displayed PHY rate guarantee that rate for file downloads?','No.','Shared airtime, overhead, retries and other bottlenecks reduce goodput.'),q('Intermediate','Layer separation','Does association prove DHCP succeeded?','No.','Wireless joining and IP configuration are separate stages.')],
exams:[q('Beginner','Service set','Which identifies a particular basic service set?','BSSID.','SSID names the network and can span multiple AP radios.',['Default gateway','BSSID.','DNS suffix','TCP port']),q('Troubleshooting','Backend','A client associates but lacks a usable IP address. What should be checked next?','Address assignment and AP-to-client-segment forwarding, including VLAN/DHCP reachability.','Association alone does not validate the backend path.'),q('Intermediate','Capacity','Which resource is shared by competing wireless transmissions on a channel?','Airtime.','Radio contention and scheduling allocate transmission opportunities.',['Each client’s private fiber','Airtime.','DNS TTL','Disk IOPS']),q('Troubleshooting','Signal','Why can strong signal coexist with poor performance?','Interference, contention, retries, backend limits or application delays may dominate.','Received power is only one measurement.'),q('Design','Width','Why not always use the widest possible channel?','It can consume more spectrum and reduce reuse, increasing contention in dense deployments.','Peak single-link rate and system capacity are different design objectives.'),q('Advanced','Power','Why can high AP power create an asymmetric coverage problem?','The client may hear the AP while lacking enough transmit power or a clean return path.','Both directions must work.'),q('Security','Certificates','Why validate the authentication server certificate on enterprise Wi-Fi clients?','To authenticate the intended service and reduce credential exposure to impersonation.','A familiar SSID is not a trustworthy identity proof.'),q('Intermediate','Roaming','A client keeps the SSID but changes BSSID. What may have happened?','It may have roamed to another basic service set.','The network name can remain constant across APs.'),q('Troubleshooting','Virtualization','Does ip link in ordinary WSL reveal host Wi-Fi airtime utilization?','No.','It usually describes a virtual network interface, not the physical radio.'),q('Design','Acceptance','What evidence should accompany a successful channel change?','Comparable workload observations of retries, utilization, latency and user service, including roaming where relevant.','A configuration screenshot alone does not prove improved service.')],
glossary:{WLAN:'Wireless local area network.',SSID:'Wireless network name.',BSSID:'Identifier for a basic service set.',Airtime:'Time spent using radio transmission resources.'},related:['s0-g2-t0','s0-g2-t8','s0-g2-t9','s0-g2-t10'],sources:[refs.wlan,refs.radio,refs.link]
}),lesson(3,{
title:'Ethernet',subtitle:'Connect the physical link to the frame-forwarding behavior.',
definition:'Ethernet is a family of IEEE 802.3 link technologies that carry frames over media such as copper and fiber. Modern switched Ethernet commonly uses point-to-point full-duplex links. Ethernet is not synonymous with IP, Internet access or an RJ45 connector.',
purpose:'A common link technology lets interfaces and switches exchange frames with defined addressing, framing and error-detection behavior. Its physical variants support different media, distances and rates while upper-layer protocols can share the link.',
mental:'Treat Ethernet as the local delivery conveyor carrying labelled containers. The physical medium moves signals; frame fields tell the receiving link layer what arrived. The conveyor does not interpret a website name, and an intact frame does not guarantee the remote application processed its contents.',
components:['PHY and medium: encoding/signalling, copper pairs or optical transmitter/receiver and cable.','MAC function: frame transmission/reception and link-layer addressing.','Switch ports and forwarding database: learned source locations within VLANs.','Frame check sequence: CRC-based accidental corruption detection, not cryptographic authentication.'],
mechanism:['Link partners establish compatible physical operation according to the supported Ethernet variant. Auto-negotiation, training and optical compatibility are technology-specific; do not carry a legacy 10/100 rule into every modern interface.','A sender constructs a frame with destination/source MAC, type/length information, payload and FCS. Ethernet II uses EtherType to identify payload protocols, for example IPv4. VLAN tagging adds another header field when used.','A switch receives the frame, applies ingress classification and forwarding policy, learns the source where appropriate, and selects egress based on destination and VLAN. Store-and-forward switching receives a whole frame before forwarding; other forwarding modes have different latency/error tradeoffs.','At each egress, transmission consumes link capacity. A receiving NIC validates acceptable frames and passes their payload to the relevant protocol stack. Link success does not supply IP addressing, routing, DNS or application authorization.'],
flow:[['Establish link','Check compatible medium, rate and physical operation.'],['Encode a frame','Source/destination MAC and payload protocol identify local delivery.'],['Switch within scope','The switch applies VLAN and forwarding state to choose eligible egress.'],['Validate and deliver','The receiver checks framing/error information and passes payload upward.']],
comparison:[['Copper Ethernet','Electrical signalling over a supported cable plant','Cable quality and reach must match the specific variant.'],['Fiber Ethernet','Optical signalling with matching optics/fiber','Wavelength, mode, polarity and reach matter.'],['Ethernet frame','Link-layer delivery unit','Can carry IP or non-IP protocols.'],['IP packet','Network-layer delivery unit','May cross many different links.']],
example:'A server connects at 100 Mb/s when 1 Gb/s was expected. The negotiated result could reflect cable/pair problems, advertised capabilities or administrative constraints. Forcing a speed before inspecting both endpoints can hide the cause or take the link down.',
commands:[cmd('ip -br link\nip -s link show','Inspect link state, MTU, address and generic traffic/error counters.','UP is administrative state; LOWER_UP indicates lower-layer carrier where meaningful. Virtual interfaces have different semantics.'),cmd('ethtool eth0','Read supported/advertised modes, negotiated speed/duplex and link detection for the named interface.','Replace eth0 only after inspecting interface names. Virtual NICs may omit physical details or report synthetic values. ethtool must be installed; this read form changes nothing.','Linux / ethtool, optional physical NIC')],
configuration:'Use a tested cable/optic matrix and supported negotiation policy for both ends. Identify physical ports and current settings before a change. Save interface configuration and prepare console/out-of-band access. After a planned correction, verify negotiated state, error deltas and actual bidirectional traffic; restore the previous settings if the agreed tests fail.',
ports:'Ethernet has no TCP/UDP port. EtherType identifies payload protocol at the link layer; 0x0800 is IPv4, 0x86DD IPv6 and 0x0806 ARP. Physical switch ports and transport-layer port numbers are different meanings of “port.”',
production:'Rack servers use documented switch interfaces, supported optics/cables and monitored counters. A deployment checklist includes rate, duplex, VLAN and MTU consistency, then application traffic. Redundant NICs provide resilience only with a correct bonding/teaming and switch design; two cables alone can introduce a loop or an unused backup.',
troubleshooting:[['Symptom','A new server link is slower than expected and receive errors rise.'],['Hypotheses','Damaged medium, unsupported optic, incompatible settings or a legacy duplex mismatch.'],['Test','Read both endpoints, inspect counter deltas during a bounded workload, and compare with the approved media specification.'],['Observation','Synthetic case: both ends negotiate the same lower rate; replacing the suspect patch cable in a maintenance window restores the expected rate and stops error growth.'],['Conclusion / next test','The controlled swap supports a cable-path cause. Validate the replacement under normal load; do not infer every low-speed link has the same fault.'],['Fix and verify','Retire the failed cable, document ports/media and confirm stable rate, bidirectional throughput and clean counter deltas.']],
security:'Physical access can expose a network segment. Enforce access policy and protect switch management. Ethernet FCS detects many accidental errors but is not a message authenticator; an attacker can construct a new valid frame. Confidentiality and trustworthy peer identity require higher-layer or link-security controls.',
performance:'Line rate measures bits carried by the link, including work that is not useful application payload. Frame headers, FCS, preamble and spacing consume capacity; small packets can make packet-processing capacity the limit. A fast access port cannot remove congestion on a narrower uplink.',
mistakes:['Equating all Ethernet with copper RJ45.','Using link-up as proof that IP and DNS are correct.','Forcing one endpoint’s duplex without checking its partner and technology.'],
lab:{objective:'Build a physical-link evidence record and distinguish carrier from service health.',requirements:'Browser and notebook; optional Linux interface inventory. Hardware counters may be unavailable in VMs/WSL.',topology:['Host NIC','Cable / optic','Switch port','Uplink / gateway'],steps:['Read the four stages of the flow and annotate where a damaged cable differs from a wrong VLAN.','Optionally run ip -br link and record one interface’s state/MTU without publishing its MAC.','If a physical Linux NIC and ethtool are available, inspect both expected and negotiated capabilities; otherwise label physical fields unavailable.','Use the synthetic cable-swap result above to write a hypothesis, controlled test and supported conclusion.','List the checks still needed after link restoration: addressing, neighbor, route and application policy.'],verification:'The report labels physical versus virtual evidence, includes counter deltas rather than a lifetime total, and does not claim successful application delivery from carrier alone.',troubleshooting:'Operation not supported for ethtool on a virtual adapter limits the evidence; it does not justify changing the driver or forcing speed.',challenge:'Why can a switch face packet-per-second pressure with tiny frames even when byte-rate utilization is below its advertised aggregate rate?',cleanup:'No link settings changed. Hardware substitution exists only in the synthetic case.'},
quick:[q('Beginner','Layers','Can Ethernet carry traffic other than IP?','Yes.','ARP is one familiar example with a separate EtherType.'),q('Intermediate','Integrity','Is an Ethernet FCS a cryptographic authenticator?','No.','It is error detection, not proof of a trusted sender.'),q('Intermediate','Media','Does Ethernet require an RJ45 copper cable?','No.','Ethernet also has fiber and other physical variants.')],
exams:[q('Beginner','Protocol','What is Ethernet primarily in this course?','A family of link technologies carrying frames.','It is not a DNS service or an IP routing protocol.',['A family of link technologies carrying frames.','An application port','A hostname resolver','Only a cable connector']),q('Intermediate','Type','Which EtherType identifies IPv4 in Ethernet II?','0x0800.','0x0806 identifies ARP and 0x86DD identifies IPv6.',['0x0806','0x86DD','0x0800.','TCP 443']),q('Troubleshooting','Rate','A link negotiates below the expected speed. Why inspect both ends first?','Capabilities, media and administrative settings at either end can constrain the result.','Forcing a local setting can interrupt service or mask the cause.'),q('Intermediate','State','What does link carrier alone fail to prove?','Correct IP addressing, routing, policy and application availability.','Those require additional layer-specific evidence.'),q('Advanced','Forwarding','How does store-and-forward differ from forwarding before the full frame arrives?','It buffers the full frame before egress and can inspect its completed error check.','Forwarding mode affects latency and corrupted-frame behavior.'),q('Security','FCS','Why does valid FCS not prove a trusted sender?','A sender can construct a frame and calculate its CRC.','Accidental error detection is not source authentication.'),q('Design','Optics','What should be checked before installing fiber optics?','Supported module compatibility, wavelength, fiber mode, reach and polarity.','A matching connector alone is insufficient.'),q('Troubleshooting','Counters','Why compare error counters over time?','Lifetime totals do not reveal whether errors are occurring during the incident.','A timestamped delta can be correlated with the workload.'),q('Advanced','Capacity','Why can tiny frames stress a device at modest byte throughput?','They increase per-packet processing work per unit of useful data.','Packet and bit capacity are separate constraints.'),q('Design','Redundancy','Why do two connected NIC cables not prove resilience?','Teaming/bonding, switch topology, policy and common failure domains determine actual behavior.','Incorrect redundant links can be inactive or create faults.')],
glossary:{Ethernet:'IEEE 802.3 link-technology family.',PHY:'Physical-layer signalling function.',EtherType:'Ethernet II field identifying payload protocol.',FCS:'Frame check sequence used for error detection.'},related:['s0-g2-t4','s0-g2-t5','s0-g2-t10'],sources:[refs.eth,refs.duplex,refs.link,refs.tool,refs.mac]
})];
lessons.push(lesson(4,{
title:'MAC addresses',subtitle:'A local forwarding identity is not a permanent identity for a person or machine.',
definition:'A Media Access Control address identifies a link-layer interface or destination in technologies such as Ethernet. The common Ethernet form is 48 bits, often written as six hexadecimal octets. Its role is local frame delivery, not global IP routing or user authentication.',
purpose:'A shared link needs a way to distinguish recipients, and a switch needs destination identifiers for forwarding. MAC addressing supplies this function while allowing IP and other protocols to use the same link. The address seen on the wire can be locally assigned, virtual or randomized.',
mental:'A MAC is like a delivery label valid inside the current sorting area. At a routed boundary the next local envelope gets new labels. The analogy stops at identity: labels can be copied or changed, and a manufacturer prefix is not proof of ownership or trust.',
components:['48-bit address: six octets, displayed with colons, hyphens or other formatting conventions.','Individual/group bit: the least significant bit of the first octet distinguishes individual from group addressing.','Universal/local bit: the next least significant bit indicates universal versus local administration.','Switch forwarding database: maps learned source MAC and VLAN to an egress location.','Neighbor table: maps next-hop IP to link address on the endpoint; it is not the same as a switch forwarding table.'],
mechanism:['An endpoint chooses a route and next hop before constructing the outgoing Ethernet header. If needed, IPv4 ARP or IPv6 Neighbor Discovery obtains the next-hop link address. The application’s final IP destination can be remote while the Ethernet destination is the local router.','A switch learns a valid source location from arriving traffic in its VLAN context. It looks up the destination and either forwards toward a known location or uses appropriate flooding/group handling. Entries age and may move when devices relocate.','At a router, the old frame is removed and a new one is constructed for the next link. The original source MAC is normally not carried as the new source MAC. A conventional router does not learn the remote endpoint’s Ethernet address through an arbitrary routed path.','Virtualization, failover and client privacy can change observed addresses. A new address is not automatically an intruder; a duplicated address or rapidly moving location can indicate a real conflict, loop or legitimate mobility. Correlate with asset and topology evidence.'],
flow:[['Choose a next hop','The IP route determines which local neighbor must receive the frame.'],['Resolve its MAC','Use neighbor state or resolution; this is not a DNS lookup.'],['Learn and forward','Switches learn source location and use destination MAC in the correct VLAN.'],['Replace at routing','The router creates a new local envelope; link labels change while ordinary end-to-end IP endpoints remain.']],
comparison:[['MAC address','Link-layer destination/source','Usually relevant within a link or bridged segment.'],['IP address','Network-layer endpoint and routing input','Can identify a destination beyond the local segment.'],['Neighbor table','IP-to-link mapping','Examined on hosts and routers.'],['Switch forwarding table','MAC/VLAN-to-port mapping','Examined on a bridge or switch.']],
example:'The journey uses client MAC 02:00:00:00:00:10 and router ingress MAC 02:00:00:00:00:01. The first octet 02 has the local bit set and individual bit clear: this is a locally administered unicast example. It does not identify a hardware vendor. The addresses are synthetic and should not be assigned to a live shared segment for the lab.',
commands:[cmd('ip -br link\nip neigh show','Compare local interface link addresses with cached next-hop mappings.','The local interface MAC and the gateway neighbor MAC are different roles. STALE is not synonymous with unreachable.'),cmd('Get-NetAdapter | Select-Object Name, Status, MacAddress, LinkSpeed','Inspect Windows adapter addresses and reported link rates.','Virtual and physical adapters can coexist. A reported address is not a verified asset owner or a guarantee of physical bandwidth.','Windows 11 / PowerShell')],
configuration:'Most learners should leave addresses under the operating system or virtualization platform’s management. If a documented failover or virtual service requires a managed MAC, allocate it within the relevant scope and test collision/mobility behavior. Preserve the old configuration and neighbor/forwarding observations before an authorized change. Do not copy a production address for a lab.',
ports:'MAC addressing has no TCP/UDP port. ARP uses its own Ethernet payload type. IPv6 Neighbor Discovery uses ICMPv6; it is not ARP and has no TCP/UDP port.',
production:'Operators correlate switch location, VLAN, neighbor mappings and inventory to identify an endpoint. Wireless address randomization and virtual machines make a single MAC a weak long-term inventory key. For a moving service, distinguish expected failover from continuous MAC flapping and retain timestamps from both switch ports.',
troubleshooting:[['Symptom','A device becomes intermittently unreachable and its learned MAC alternates between ports.'],['Hypotheses','Layer 2 loop, duplicate address, legitimate teaming/failover or device relocation.'],['Test','Correlate timestamped forwarding changes with topology, bond configuration and authorized device inventory.'],['Observation','Synthetic evidence: two independent VMs were cloned with the same configured MAC and are active in one VLAN.'],['Conclusion / next test','The duplicate can redirect frame delivery unpredictably. Verify which instances must remain active before correcting the clone.'],['Fix and verify','Assign a unique managed address to the affected clone under an approved VM procedure. Confirm stable forwarding, refreshed neighbor resolution and both VM services; retain rollback state.']],
security:'MAC addresses are observable and often changeable. Do not use them as a substitute for authenticated user/device identity. Switch protections and authenticated access can constrain misuse, while encryption protects payload independently. Vendor lookup can assist inventory but cannot prove which physical product or person sent a frame.',
performance:'Large address churn can stress forwarding/neighbor state and increase flooding. Aging is normal and does not itself imply a performance incident. Measure unknown-unicast behavior, table limits and actual traffic before increasing timeouts; a longer stale mapping can prolong incorrect delivery after a move.',
mistakes:['Thinking a MAC is globally routed across the Internet.','Reading 02 as a vendor prefix for a universally assigned address.','Confusing a host neighbor table with a switch MAC table.'],interactive:'journey',
lab:{objective:'Track MAC roles across a routed path and interpret locally administered addressing.',requirements:'Packet journey and notebook; optional read-only host inventory.',topology:['Client 02:…:10','Router ingress 02:…:01','Router egress 02:…:02','Server 02:…:20'],steps:['Step through the journey and copy the source/destination MAC fields before and after the router.','Keep a separate column for source/destination IP to avoid mixing the address layers.','Convert the first octet 02 to binary 00000010; identify the two low-order bits.','Compare the neighbor-table and switch-table roles without inventing switch data from host output.','Diagnose the cloned-VM scenario and write an identity-preserving correction plan.'],verification:'The worksheet shows next-hop MAC replacement, unchanged ordinary IP endpoints, and correct local/unicast bit interpretation. It does not infer vendor identity from 02.',troubleshooting:'Different MAC formatting is not a different address. Virtual interfaces and randomized WLAN addresses should be labelled instead of forced to match a vendor lookup.',challenge:'A host talks to several remote IPs through one gateway. Explain why its neighbor table may contain only that gateway for those flows.',cleanup:'Reset the journey. Do not modify adapter or VM addresses.'},
quick:[q('Beginner','Scope','Is a MAC normally the address used by Internet routers to choose a remote network?','No.','IP routing and local frame delivery use different fields.'),q('Intermediate','Learning','Does a switch normally learn from source or destination MAC?','Source MAC.','The ingress location tells it where that source was observed.'),q('Intermediate','Identity','Can a locally administered MAC be legitimate?','Yes.','Virtualization and privacy are common reasons.')],
exams:[q('Beginner','Size','How many bits are in the common Ethernet MAC address?','48.','Six octets contain 6 × 8 bits.',['32','48.','64','128']),q('Intermediate','Bits','What does first octet 02 indicate in the common bit interpretation?','Locally administered individual/unicast address.','Binary 00000010 has the local bit set and the group bit clear.'),q('Troubleshooting','Tables','Which table maps a next-hop IP to a link address on a host?','Neighbor table.','A switch forwarding database maps MAC/VLAN to port instead.',['DNS cache','Neighbor table.','IP route metrics','Process table']),q('Intermediate','Router','Does an ordinary router preserve the client source MAC on the next Ethernet link?','No; it builds a new link header using its egress interface and next hop.','The link envelope changes at the routed boundary.'),q('Advanced','Remote peers','Why might many remote server IPs use one neighbor entry on a client?','They can share the same selected local gateway.','The client resolves the next hop, not each off-link endpoint’s MAC.'),q('Security','Identity','Why is a MAC allowlist weak authentication?','Addresses can be observed and copied or locally changed.','It does not provide a cryptographic proof of device identity.'),q('Troubleshooting','Flapping','Does a moving MAC prove an attack?','No; investigate loops, duplicate addresses, mobility and teaming/failover.','Context and timestamps distinguish plausible causes.'),q('Intermediate','Broadcast','What is the conventional Ethernet broadcast destination?','FF:FF:FF:FF:FF:FF.','All address bits are one; broadcast scope is still constrained by the segment.'),q('Design','Inventory','Why use more than a MAC as a durable inventory key?','Interfaces, VMs and privacy settings can change the observed address.','Inventory should correlate managed identifiers and context.'),q('Advanced','Aging','Why can blindly lengthening neighbor/forwarding aging be harmful?','It can preserve stale mappings after a move and delay recovery.','Longer retention is not a universal fix for churn.')],
glossary:{MAC:'Media Access Control link address.',Unicast:'Delivery addressed to an individual destination.',Multicast:'Delivery addressed to a group.','Neighbor cache':'Stored mapping/state for adjacent network-layer neighbors.'},related:['s0-g2-t0','s0-g2-t3','s0-g2-t5'],sources:[refs.mac,refs.arp,refs.neigh,refs.win]
}),lesson(5,{
title:'Frames',subtitle:'Define what is counted before comparing packet captures and MTUs.',
definition:'A frame is a link-layer delivery unit. In the Ethernet II example, it contains destination/source MAC fields, an EtherType, payload and an FCS. Frames are local to a link technology; they are not interchangeable with IP packets or application messages.',
purpose:'Framing gives a receiver boundaries, local addressing, payload identification and error-detection information. Upper layers can send their own units inside the payload without controlling the physical signalling directly. The exact layout depends on the link and encapsulation.',
mental:'A frame is an envelope around an IP packet. A router opens that envelope and uses a fresh one on the next link. The analogy has limits: Ethernet padding is outside the IP packet length, and captures may hide or transform parts of the envelope before software sees them.',
components:['Ethernet II base header: 6-byte destination, 6-byte source and 2-byte EtherType.','Optional VLAN tag: a common 802.1Q tag adds 4 bytes; other encapsulations can add more.','Payload and padding: ordinary untagged Ethernet data field is at least 46 bytes and commonly up to 1500 bytes.','FCS: 4 bytes of CRC-based error detection, often stripped before host packet capture.','Preamble/start delimiter and inter-frame gap: consume link time but are not counted in the usual 64–1518-byte untagged MAC-frame size.'],
mechanism:['The sender places the upper-layer unit into the data field. If it is too short for the Ethernet minimum, padding supplies the required frame size. The IP Total Length remains the IP packet length; it does not grow merely because Ethernet adds padding.','For an ordinary untagged Ethernet II frame carrying a 1500-byte IP packet, 14 bytes of header and 4 bytes of FCS produce a 1518-byte MAC frame. Add preamble/start delimiter and inter-frame spacing when calculating wire-time cost; do not silently mix these accounting boundaries.','A switch forwards eligible frames within its link-layer domain. A router removes the received frame and forwards the IP packet in a newly constructed frame on the next link. VLAN membership, tagging and encapsulation can change what the next capture shows.','The receiving hardware may strip the FCS or VLAN metadata; offloads can also make a host capture differ from actual wire packets. A suspicious capture length or apparent outgoing checksum fault needs observation-point and offload context before declaring corrupted traffic.'],
flow:[['Build payload','The IP packet has its own length, independent of Ethernet padding.'],['Wrap and pad','Add link addresses, EtherType, optional tag and required padding.'],['Transmit and check','The link sends the frame; the receiver checks error information.'],['Unwrap or forward','A destination passes payload upward; a router builds a new link frame.']],
comparison:[['IP MTU 1500','Maximum IP packet for this link configuration','Does not mean a 1500-byte total Ethernet frame.'],['Untagged MAC frame 1518','14 header + 1500 payload + 4 FCS','Excludes preamble and inter-frame spacing.'],['Single tagged equivalent 1522','Adds a 4-byte VLAN tag','Check platform frame-size accounting.'],['Host capture length','What capture software receives','May omit FCS and offloaded metadata.']],
example:'A capture shows a 1514-byte Ethernet packet carrying 1500 bytes of IP. That is consistent with a 14-byte header and an FCS stripped by the capture path. It is not proof that the wire omitted its FCS, nor that the IP MTU should be set to 1514.',
commands:[cmd('ip -d link show\nip -s link show','Inspect link details and counters, including software-visible VLAN devices where present.','The host’s configured MTU and metadata are not a full wire-format capture. VLAN offload and virtual paths can hide details.'),cmd('ethtool -k eth0','Inspect offload feature status without changing it.','Some features may be fixed or unsupported; eth0 is an example interface name. Offload state helps interpret captures but is not evidence of malformed wire traffic.','Linux / ethtool, optional NIC')],
configuration:'Align VLAN tagging and frame-size support across the intended path. Vendor terms such as MTU, jumbo size and maximum frame length can count different headers, so document the counting convention. Validate both untagged/tagged paths before rollout and keep previous interface settings. Do not disable offloads globally as a first response to an ambiguous capture.',
ports:'An Ethernet frame’s EtherType is distinct from TCP/UDP ports inside its payload. Some frames carry protocols that do not contain transport ports at all, such as ARP.',
production:'Capture procedures record interface, direction, timestamp, encapsulation and offload context. Engineers compare switch counters with host evidence and use an authorized observation point appropriate to the question. Storing every payload indefinitely is unnecessary for most frame-size diagnoses and increases privacy exposure.',
troubleshooting:[['Symptom','A monitoring capture seems four bytes shorter than the expected maximum Ethernet frame.'],['Hypotheses','FCS stripping, different encapsulation or an incorrect comparison boundary.'],['Test','Compare captured header/IP length, capture mechanism and documented FCS handling.'],['Observation','Synthetic evidence: 14-byte Ethernet header plus 1500-byte IP length, no recorded FCS field.'],['Conclusion / next test','This is consistent with FCS stripping; it does not establish a wire defect. Correlate physical error counters if corruption is suspected.'],['Fix and verify','Correct the analysis accounting and retain the capture-context note. Change no interface MTU unless independent path evidence requires it.']],
security:'FCS is not encryption or authenticated integrity. Captured frames can expose addresses, protocol metadata and plaintext application content. Prefer bounded captures on authorized interfaces with data minimization; this introductory lab uses a synthetic frame rather than collecting other users’ traffic.',
performance:'Small payloads incur a larger proportion of link overhead. A minimum-sized untagged frame is 64 bytes from destination MAC through FCS, but its transmission opportunity also consumes preamble/start delimiter and gap time. Different offloads and jumbo frames change endpoint work; they do not eliminate path compatibility requirements.',
mistakes:['Calling 1518 bytes the IP MTU of ordinary Ethernet.','Adding Ethernet padding to IP Total Length.','Treating host capture representation as a perfect wire image.'],interactive:'journey',
lab:{objective:'Reconcile Ethernet frame, IP packet and capture lengths without a live capture.',requirements:'Notebook or calculator; the supplied synthetic header/payload dimensions.',topology:['Ethernet header 14 B','IP packet 1500 B','FCS 4 B','Wire-time overhead outside frame'],steps:['Calculate the untagged MAC frame length for a 1500-byte IP packet.','Add one 4-byte VLAN tag and label what counting boundary you used.','Predict the software capture length if the FCS is stripped and the VLAN tag is absent: 14 + 1500.','For a 28-byte IPv4/ICMP packet, calculate the padding needed to fill the 46-byte minimum data field.','Use the journey to explain why the router constructs a new Ethernet frame around the forwarded packet.'],verification:'Expected results: 1518 bytes untagged, 1522 with one tag, 1514 captured without FCS, and 18 bytes of padding for the 28-byte IP example. IP length remains 28.',troubleshooting:'These values assume ordinary Ethernet II without extra tags, tunnels or IP options. If a platform reports another MTU/frame convention, document it before comparison.',challenge:'Using 8 bytes of preamble/start delimiter and 12 byte-times of gap, calculate the wire-time budget of a minimum 64-byte frame: 84 byte-times.',cleanup:'No capture files or NIC changes were created. Keep the annotated length calculation.'},
quick:[q('Beginner','Encapsulation','Is a frame the same as an IP packet?','No.','The link frame can contain the IP packet as payload.'),q('Intermediate','MTU','Does IP MTU 1500 include the Ethernet header and FCS?','No.','Those lie outside the IP packet.'),q('Intermediate','Capture','Can host captures omit Ethernet FCS?','Yes.','Hardware or the capture path can strip it.')],
exams:[q('Beginner','Header','What is the ordinary Ethernet II header size without a VLAN tag?','14 bytes.','Two 6-byte addresses and a 2-byte EtherType total 14.',['8 bytes','14 bytes.','20 bytes','64 bytes']),q('Intermediate','Size','What is 14 + 1500 + 4 describing?','A 1518-byte untagged Ethernet MAC frame including FCS.','Preamble and gap are outside this count.'),q('Intermediate','Padding','How much padding does a 28-byte IP packet need in a minimum 46-byte Ethernet data field?','18 bytes.','Padding fills the data field but does not increase IP Total Length.',['0 bytes','4 bytes','18 bytes.','46 bytes']),q('Troubleshooting','Capture','Why might software display 1514 bytes for a maximum-size untagged IP-over-Ethernet frame?','Its capture path may omit the 4-byte FCS.','The observation is consistent with normal capture processing.'),q('Advanced','Tagging','What must be stated when comparing a vendor frame-size limit with an IP MTU?','Which headers, tags and FCS the platform includes in its reported limit.','Identical numbers can refer to different boundaries.'),q('Security','Integrity','Can a valid FCS protect against intentional frame modification by a sender?','No.','A malicious sender can compute a valid CRC for modified content.'),q('Intermediate','Router','What happens to the incoming Ethernet envelope at a routed boundary?','It is removed; the forwarded IP packet is encapsulated for the next link.','The outgoing link addresses and FCS describe a different frame.'),q('Advanced','Offload','What should be checked before blaming an outgoing checksum anomaly in a host capture on the network?','Capture direction and checksum/offload behavior.','Software may observe a packet before hardware finishes checksums.'),q('Design','Privacy','Why use a bounded synthetic frame for an introductory lab?','It teaches field accounting without collecting unrelated users’ payloads.','Real capture authorization and data handling remain separate operational responsibilities.'),q('Advanced','Wire time','Why does a 64-byte frame occupy more than 64 byte-times of link opportunity?','Preamble/start delimiter and the required inter-frame gap also consume time.','The model’s 8 + 12 extra byte-times yield 84 for this example.')],
glossary:{Frame:'Link-layer unit with local delivery and error-checking fields.',Padding:'Extra data-field bytes used to meet a link minimum.','Encapsulation':'Wrapping one protocol unit inside another.','Offload':'Work performed by hardware or a lower layer on behalf of host software.'},related:['s0-g2-t3','s0-g2-t6','s0-g2-t7'],sources:[refs.eth,refs.mac,refs.link,refs.tool]
}),lesson(6,{
title:'Packets',subtitle:'Follow network-layer state through a router without confusing it with a frame.',
definition:'An IP packet is a network-layer unit containing an IP header and payload. Routers use destination and forwarding policy to move it toward another network. IP delivery is best effort: packets can be lost, duplicated, delayed or reordered.',
purpose:'IP lets traffic cross heterogeneous links without requiring one enormous shared Ethernet segment. A host can send toward a remote address through multiple next hops, each of which uses its own link framing. Reliability and application meaning are provided by other layers when needed.',
mental:'The IP packet is the addressed document inside changing local envelopes. Routers inspect its network destination and reduce its remaining forwarding lifetime. This analogy excludes NAT and tunnels unless stated: those mechanisms can rewrite addresses or add an outer packet with another destination.',
components:['IP source/destination: endpoint addresses used in network-layer communication.','IPv4 TTL / IPv6 Hop Limit: bounds forwarding loops by decreasing at routers.','IPv4 header checksum: protects the IPv4 header; IPv6 has no equivalent base-header checksum.','Protocol/Next Header: identifies the following protocol, possibly a transport protocol or extension header.','Payload: may contain TCP, UDP, ICMP or another supported protocol; not every packet contains ports.'],
mechanism:['The source builds a network-layer packet and selects a route. Local policy, destination prefix and route metrics can affect the choice. It then wraps the packet for the selected next hop on the outgoing interface.','A conventional router removes the received link envelope, validates the relevant packet conditions, selects forwarding state and reduces TTL/Hop Limit. A packet that cannot be forwarded within its lifetime is discarded; diagnostic responses are subject to implementation and policy.','The router builds new link framing for the next hop. In ordinary forwarding without NAT, source/destination IP and transport ports remain the same while TTL changes. IPv4 header checksum must reflect the changed header. A transparent Layer 2 switch does not normally decrement IP TTL.','At the destination, IP delivers payload to the indicated protocol. TCP offers an ordered reliable byte stream to applications, while UDP does not provide that service itself. Neither a successful ping nor an arriving packet proves a particular application transaction completed.'],
flow:[['Create IP unit','The source chooses endpoints, protocol and initial lifetime.'],['Choose next hop','The local route selects an outgoing interface and neighbor.'],['Route and reframe','A router reduces TTL/Hop Limit and constructs a fresh link envelope.'],['Deliver upward','The destination hands payload to the next protocol; the application still performs its own work.']],
comparison:[['Frame','Link-layer unit','Link addresses normally change at a router.'],['IP packet','Network-layer unit','Ordinary end-to-end IP addresses remain across routers.'],['TCP segment','Transport unit carrying part of a byte stream','Ports and TCP state exist inside the IP payload.'],['Application message','Protocol-specific meaning','Can span multiple packets or share a transport stream.']],
example:'The simulator sends IPv4 192.0.2.10 → 198.51.100.20 with TCP 51514 → 443 and TTL 64. After one router, TTL is 63 and Ethernet addresses identify router egress → server. NAT, tunnels, VLAN tags and TCP state are explicitly excluded from this small model.',
commands:[cmd('ip route get 198.51.100.20','Inspect the local forwarding choice without sending a network packet.','The route lookup may show an interface, next hop and selected source. It does not prove the remote application is reachable.'),cmd('ping -c 3 127.0.0.1','Send three ICMP echo probes to the local loopback address.','Successful replies demonstrate this local ICMP path only. They test neither physical Ethernet nor the remote TCP 443 application.','Ubuntu 24.04 / Bash + iputils')],
configuration:'Addressing, prefix lengths and routes belong to a managed network design. Before changing them, identify the controlling service and retain a recovery path. Validate route selection and an authorized service test in both directions after changes. Keep NAT and tunnel behavior documented separately so a packet trace is interpreted against the actual architecture.',
ports:'IP itself uses protocol identifiers rather than TCP/UDP ports. TCP and UDP carry ports inside the IP payload. ICMP uses types/codes, not port numbers. The example destination TCP 443 is a convention, not proof that the payload is valid or secure HTTPS.',
production:'An incident trace follows a specific flow with timestamps and observation points: source, edge and destination. Engineers account for load balancers, NAT and tunnels before comparing address fields. Packet arrival proves transport of a unit to that point; service health requires the expected application response and authorization outcome.',
troubleshooting:[['Symptom','A remote flow repeatedly expires before reaching its destination.'],['Hypotheses','Routing loop, unexpectedly long path or an unusually low initial lifetime.'],['Test','Compare bounded path observations and route tables at repeated hops; do not infer a loop from one missing probe response.'],['Observation','Synthetic evidence: two routers point the target prefix toward each other and the packet lifetime falls on every pass.'],['Conclusion / next test','Conflicting forwarding entries form a loop. Verify the intended destination route and control-plane origin.'],['Fix and verify','Correct the approved route source and verify convergence, stable forwarding and complete bidirectional application transactions. Increasing TTL would only hide the symptom temporarily.']],
security:'Source IP alone is not authenticated identity, and port 443 alone does not prove encrypted content. Enforce appropriate routing/security policy and authenticate at the intended layer. Permit necessary diagnostic signaling according to policy; indiscriminate ICMP blocking can obscure failures and interfere with path-size discovery.',
performance:'Packet loss, reordering and latency interact with transport behavior. Small packets can increase per-packet processing, while large packets reduce some overhead but must fit the path. Application writes, TCP segments and captured packets do not have a universal one-to-one relationship because of buffering and offloads.',
mistakes:['Decrementing TTL at every switch in a topology diagram.','Claiming UDP can never be reliable at the application level.','Assuming port 443 proves a secure successful application transaction.'],interactive:'journey',
lab:{objective:'Record exactly which fields change at a single routed hop.',requirements:'Browser journey with ordinary IPv4 forwarding selected by the fixed scenario; optional loopback ping.',topology:['Client / TTL 64','Layer 2 switch','Router / TTL 63','Server'],steps:['At each journey step, record source IP, destination IP, both MAC addresses, TCP ports and TTL.','Predict the router step before advancing. Check that the switch preserves TTL and the router reduces it.','Use Previous and Reset to compare the two Ethernet headers.','Optionally run the bounded loopback ping and write its limited conclusion.','Analyze the two-router loop case; explain why changing the route addresses the cause and raising TTL does not.'],verification:'IPs and TCP ports remain constant in the no-NAT model; MACs change at routing; TTL changes 64 → 63 only at the router. The loopback result is not described as an Internet test.',troubleshooting:'Real NAT/tunnels create different observations. The simulator intentionally omits them and is not a universal packet decoder.',challenge:'How would your interpretation change if a capture showed an outer IP destination equal to a tunnel endpoint rather than the application server?',cleanup:'Reset the journey. The optional ping ends after three local probes; no route changed.'},
quick:[q('Beginner','Delivery','Does IP guarantee delivery?','No.','Reliability, if required, is provided by transport/application mechanisms.'),q('Intermediate','TTL','Does a normal Layer 2 switch reduce IP TTL?','No.','Routers reduce the forwarding lifetime.'),q('Intermediate','Ports','Does every IP packet contain TCP or UDP ports?','No.','ICMP and other payload protocols have different structures.')],
exams:[q('Beginner','Layer','Which unit is routed across IP networks?','IP packet.','Link frames are used to carry the packet over each local link.',['IP packet.','DNS zone','Only Ethernet FCS','Filesystem block']),q('Intermediate','TTL','A packet starts TTL 64 and crosses one ordinary router. What leaves that router?','TTL 63.','The Layer 2 switch in the example does not add another decrement.',['TTL 64.','TTL 63.','TTL 62.','TTL 0.']),q('Intermediate','Addresses','In ordinary routing without NAT, which fields remain the end-to-end addresses?','Source and destination IP.','Ethernet addresses describe each link’s next-hop delivery.'),q('Advanced','Checksum','Why does IPv4 header checksum change during ordinary forwarding?','TTL is a protected header field and changes at the router.','IPv6 has no base-header checksum equivalent.'),q('Troubleshooting','Loop','Why is raising TTL not the proper repair for two routers forwarding a prefix to each other?','It allows more loop iterations but does not correct forwarding state.','Fix the route source and verify convergence.'),q('Intermediate','Protocol','Does ICMP use TCP port 1?','No; IPv4 protocol number 1 identifies ICMP, not a TCP port.','Protocol identifiers and transport ports occupy different fields.'),q('Security','Port meaning','What can destination port 443 alone establish?','Only the selected transport endpoint number, not valid TLS or application success.','Traffic must be interpreted and authenticated at the proper layer.'),q('Troubleshooting','Probe','What does successful loopback ping fail to test?','Physical NIC, remote routing and the remote application.','Its path stays within the local host.'),q('Advanced','Transport','Can an application implement recovery while using UDP?','Yes; UDP itself does not provide TCP-style reliable ordered delivery, but an application protocol can add mechanisms.','Avoid confusing the base transport with every protocol built over it.'),q('Design','Trace','Why document NAT and tunnel boundaries before comparing captures?','They can rewrite endpoint fields or add outer headers that change what each observation represents.','The simple no-NAT model has explicitly narrower assumptions.')],
glossary:{Packet:'Network-layer unit, here an IP header plus payload.',TTL:'IPv4 forwarding lifetime reduced by routers.','Hop Limit':'IPv6 forwarding lifetime field.','Next hop':'Adjacent forwarding destination selected for a packet.'},related:['s0-g2-t4','s0-g2-t5','s0-g2-t7'],sources:[refs.v4,refs.v6,refs.route,refs.ping,source('RFC 9293: TCP','https://www.rfc-editor.org/rfc/rfc9293'),source('RFC 768: UDP','https://www.rfc-editor.org/rfc/rfc768')]
}),lesson(7,{
title:'MTU',subtitle:'A packet that fits the first interface may still be too large for the path.',
definition:'The Maximum Transmission Unit limits the size of a network-layer packet carried over a link in the stated configuration. Path MTU is the smallest effective MTU along a path. An IP MTU of 1500 bytes is not a 1500-byte application payload or a 1500-byte total Ethernet frame.',
purpose:'Every link has a finite packet-size budget. Hosts and transports need to fit packets into that budget, especially when a path includes tunnels or links with smaller limits. Correct size discovery avoids black holes and costly fragmentation/reassembly behavior.',
mental:'A package must fit through the narrowest doorway on its route. A tunnel adds an outer box that also occupies doorway space. The analogy stops at fragmentation rules: IPv4 and IPv6 handle oversized forwarding differently, and changing a TCP payload size is not the same as cutting an existing IP packet into fragments.',
components:['Interface MTU: configured network-layer size limit for the local link.','Path MTU: effective minimum across the selected direction/path, which can change after rerouting.','Headers: IP, transport and encapsulation consume part of the available budget.','IPv4 DF flag and ICMP fragmentation-needed signaling support classical discovery.','IPv6 Packet Too Big signaling and packetization-layer probing help senders adapt; routers do not fragment IPv6 packets.'],
mechanism:['A sender forms an IP packet within its current size estimate. For IPv4 without options, the IP header is 20 bytes; ICMP Echo adds 8 bytes. Thus 1472 bytes of Echo data plus 28 bytes of headers make a 1500-byte IPv4 packet. This arithmetic is not the same for IPv6 or IP options.','If an IPv4 router must forward a packet larger than the next MTU and DF is set, it drops the packet and can report the next-hop MTU through ICMP. IPv4 without DF can be fragmented where supported. IPv6 routers instead discard oversized packets and send Packet Too Big; fragmentation, when used, is done by the source.','Classical PMTU discovery depends on receiving relevant feedback. If signaling is filtered, small requests may work while larger transfers stall. Packetization-layer discovery can probe sizes and infer loss without relying only on ICMP; implementations and transports vary.','TCP MSS concerns TCP data in a segment, not the whole IP packet. An IPv4 MTU 1500 with minimum 20-byte IPv4 and 20-byte TCP headers gives a 1460-byte simple data budget. Options/tunnels change the budget. MSS adjustment can help TCP paths but does not fix every UDP or non-TCP application.'],
flow:[['Calculate packet size','Add data and applicable headers; state IPv4/IPv6 and encapsulation assumptions.'],['Compare with path','The outgoing link or a downstream link may have the smaller limit.'],['Handle oversized unit','IPv4 DF and IPv6 router rules determine the response; discover usable size.'],['Adapt and verify','Send a fitting unit and verify the real service across the intended path.']],
comparison:[['Interface MTU','Local IP packet limit','Does not prove the rest of the path.'],['Path MTU','Smallest effective path limit','Can differ by direction and route.'],['TCP MSS','TCP data-size limit/advertisement','Not a universal MTU control for all protocols.'],['Ethernet frame length','Link header + payload + FCS convention','Separate accounting from IP MTU.']],
example:'A 1500-byte underlay carries a simplified tunnel with 60 bytes of total extra encapsulation. The inner IP budget is 1440. With a 20-byte IPv4 header and 8-byte ICMP header inside, Echo data must be at most 1412. The calculator uses this explicit fictional 60-byte overhead; real tunnel overhead is protocol-dependent and may vary.',
commands:[cmd('ip link show','Read configured local interface MTUs.','Loopback and virtual interfaces can have large values. Their values do not establish an external path MTU.'),cmd('ping -4 -c 3 -M do -s 1472 127.0.0.1','Demonstrate iputils IPv4 sizing syntax using only local loopback.','1472 bytes of data plus minimum IPv4/ICMP headers equals 1500. Loopback often accepts much larger packets, so success does not measure Ethernet or Internet PMTU.','Ubuntu 24.04 / Bash + iputils')],
configuration:'Choose MTU from the complete path and encapsulation plan. A jumbo deployment must account for NICs, switches, routed links and tunnels, with a documented counting convention. Before any real change, save current values, arrange out-of-band access and test representative sizes in both directions. Restore the previous managed configuration if acceptance fails; do not lower every interface blindly.',
ports:'MTU is not a TCP/UDP port. IPv4 fragmentation-needed and IPv6 Packet Too Big are ICMP-family messages. Firewall handling of these messages differs from opening a TCP port, and necessary signaling should be considered explicitly.',
production:'Engineers record MTU assumptions at overlays, VPNs, cloud edges and storage paths. They test both small control traffic and large payloads after a route or tunnel change. An incident report includes protocol, direction, exact packet size, DF behavior and received errors rather than only “ping works.”',
troubleshooting:[['Symptom','Small requests succeed through a new tunnel; larger transactions hang.'],['Hypotheses','Path MTU mismatch, filtered size feedback, application limit or loss unrelated to size.'],['Test','Compare bounded, authorized payload sizes and inspect both tunnel overhead and relevant ICMP feedback. Use the calculator for predictions, not proof.'],['Observation','Synthetic case: 1440-byte inner IP units pass; larger DF-set units fail on a 1500-byte underlay with 60 bytes of extra headers and blocked feedback.'],['Conclusion / next test','The boundary matches the calculated budget. Verify actual encapsulation size and policy before choosing the correction.'],['Fix and verify','Correct approved MTU/discovery policy or transport sizing as appropriate. Retest failing sizes and complete application transactions in both directions; confirm other protocols also work.']],
security:'Indiscriminate diagnostic-message filtering can break size discovery. Apply validated ICMP policy rather than treating all control traffic as hostile or all received messages as trustworthy. Fragmentation complicates inspection and resource accounting; use supported endpoint and firewall behavior instead of designing around unexamined fragments.',
performance:'Larger packets can reduce per-packet overhead but increase serialization time and loss cost. Fragment loss can prevent reassembly of the whole original unit. Jumbo sizes help only when the workload and complete path benefit; they are not a universal latency improvement.',
mistakes:['Setting interface MTU equal to desired application payload.','Using an IPv4 Echo data calculation unchanged for IPv6.','Calling local loopback success a path-MTU test.'],interactive:'link-budget',
lab:{objective:'Predict and diagnose the tunnel-size boundary without modifying an adapter.',requirements:'Browser link calculator and notebook; optional bounded loopback ping.',topology:['Inner payload','IP + ICMP headers','60 B tunnel overhead','1500 B underlay'],steps:['Set MTU 1500, overhead 0 and IPv4 Echo data 1472. Confirm the packet fits exactly.','Increase data to 1473 and predict failure in the model before reading the result.','Set overhead 60; find the maximum fitting Echo data and record 1412.','Keep payload 1413, choose IPv6 and explain the larger 40-byte base IP header and source-only fragmentation rule.','Return to the synthetic tunnel incident and write a verification plan that includes the real application and both directions.'],verification:'The model boundary is 1472 bytes for plain IPv4 Echo and 1412 for the stated tunnel. IPv6 without extensions has 40 + 8 bytes of inner headers. Predictions are labelled arithmetic, not measured PMTU.',troubleshooting:'The calculator omits IP options, IPv6 extension headers and variable tunnel padding. Additional headers must be counted outside this simplified model.',challenge:'For the same 1500-byte underlay and 60-byte overhead, calculate the IPv6 Echo data budget: 1392 bytes.',cleanup:'Use Reset. No MTU, firewall or tunnel configuration changed.'},
quick:[q('Beginner','Budget','Does MTU 1500 mean 1500 bytes of TCP application data?','No.','IP and transport headers consume part of the packet budget.'),q('Intermediate','IPv6','Do IPv6 routers fragment oversized packets?','No.','They report Packet Too Big; source fragmentation is a separate mechanism.'),q('Intermediate','Path','Can local MTU exceed path MTU?','Yes.','A downstream link or encapsulation can impose a smaller budget.')],
exams:[q('Beginner','Definition','What is path MTU?','The smallest effective MTU along the selected path.','It is not necessarily the sender’s local interface value.',['Largest router buffer','The smallest effective MTU along the selected path.','TCP port range','Average frame size']),q('Intermediate','Arithmetic','How much IPv4 Echo data fits MTU 1500 with no options and an 8-byte ICMP header?','1472 bytes.','1500 − 20 − 8 = 1472.',['1500 bytes','1480 bytes','1472 bytes.','1460 bytes']),q('Intermediate','Tunnel','With 1500 underlay and 60 extra bytes, what is the inner IP budget?','1440 bytes.','The outer encapsulation also has to fit the underlay.'),q('Troubleshooting','Black hole','Small transfers work but large DF-set packets stall after tunneling. What is a useful hypothesis?','Reduced effective MTU combined with missing size feedback.','Size-dependent evidence guides the test; it is not proof by itself.'),q('Advanced','IPv4 DF','What does an IPv4 router do when an oversized packet has DF set?','Drop it and, subject to applicable signaling behavior, report fragmentation needed.','It cannot simply fragment a DF-set packet to fit.'),q('Intermediate','IPv6','Where can IPv6 fragmentation occur?','At the source, not intermediate routers.','Router Packet Too Big feedback helps the source adapt.'),q('Advanced','MSS','Why is TCP MSS adjustment not a universal MTU fix?','It affects TCP data sizing, not every protocol or encapsulation path.','UDP and other traffic still need correct size behavior.'),q('Design','Validation','What should accompany a jumbo MTU rollout?','End-to-end and bidirectional compatibility tests, workload measurements and rollback access.','One interface accepting the value is insufficient.'),q('Troubleshooting','Loopback','What does the lesson’s 1472-byte loopback probe establish?','The local stack accepted that local test, not external PMTU.','Loopback bypasses the physical and remote path.'),q('Advanced','Discovery','Why can packetization-layer PMTU probing help when ICMP feedback is missing?','It can infer usable sizes through controlled probes and transport/application observations.','It still depends on correct implementation and distinguishing loss causes.')],
glossary:{MTU:'Maximum network-layer unit for the specified link configuration.',PMTU:'Path maximum transmission unit.',MSS:'Maximum TCP data segment size, distinct from IP MTU.',DF:'IPv4 Don’t Fragment flag.'},related:['s0-g2-t5','s0-g2-t6','s0-g2-t8','s0-g2-t9'],sources:[refs.mtu,refs.v6,refs.plp,refs.ping,refs.link]
}));

lessons.push(lesson(8,{
title:'Bandwidth',subtitle:'Separate available capacity, measured throughput, and useful application data.',
definition:'In this networking context, bandwidth usually describes a link or service capacity in bits per second. Throughput is the rate actually achieved over a stated interval and measurement boundary. Goodput counts useful application data, excluding the overhead and repeated work that the definition omits.',
purpose:'Capacity planning needs more precision than “the network is fast.” Distinguishing rates explains why a 1 Gb/s interface does not promise a 1 GB/s download, why protocol overhead matters, and why a server or WAN can limit a transfer even when the access switch is idle.',
mental:'A road’s carrying capacity differs from how much useful cargo arrives each second. Road width does not set travel time by itself. The analogy stops at packet transport: congestion control, acknowledgments, loss recovery and host resources interact dynamically rather than behaving like fixed vehicle lanes.',
components:['Line/service rate: physical link capacity or a contracted/policed service rate.','Measurement interval and units: seconds, decimal bits/s and bytes must be explicit.','Protocol and link overhead: headers, acknowledgments and retransmissions consume resources.','Bottleneck: the limiting link, endpoint or policy for the measured flow.','Transport state: window sizes, RTT, congestion control and loss influence sustained delivery.'],
mechanism:['Convert units before comparing claims. One byte is eight bits; 100 Mb/s is 12.5 MB/s using decimal units before any overhead. MB and MiB are different units. A displayed file-copy rate may count only application bytes.','For a transfer crossing several links, the narrowest available path resource bounds the ideal steady-state rate, but it may not be the only constraint. Competing traffic, a shaper, CPU, storage and application behavior can all produce a lower result.','TCP needs sufficient unacknowledged data in flight to use a path with a given capacity and RTT. The bandwidth-delay product estimates that flight size. At 100 Mb/s and 40 ms RTT, it is 4,000,000 bits, or 500,000 bytes. This is a sizing estimate, not a guarantee that TCP reaches that rate.','Useful throughput depends on the accounting layer. Repeated packets can raise interface byte counts without raising goodput. Short tests may emphasize startup and cache effects; long unbounded load tests can disrupt other users. Select a representative, authorized workload and a bounded interval.'],
flow:[['Define the measure','Specify direction, interval, units and whether bytes are link, IP or application data.'],['Find the constraints','Check service rate, shared links, endpoints and policy limits.'],['Measure a workload','Observe deltas under a bounded representative transfer, not just port capability.'],['Explain the gap','Separate overhead, contention, loss, transport state and endpoint limits.']],
comparison:[['Bandwidth/capacity','Potential rate at a specified boundary','A configured or advertised value is not a measurement.'],['Throughput','Achieved rate over time','State protocol layer and test conditions.'],['Goodput','Useful delivered application data rate','Excludes specified overhead/retransmission work.'],['Latency','Delay for a unit or transaction','More capacity does not remove distance or every queue.']],
example:'A 125 MB decimal file has 1,000 Mb of payload. At an ideal payload rate of 100 Mb/s it takes 10 seconds; at 1 Gb/s it takes 1 second. Actual time includes overhead, setup, congestion and endpoint work. An engineer should report this as a lower-bound calculation, not a promised completion time.',
commands:[cmd('ip -s link show','Read received/transmitted byte and packet counters for a chosen observation interval.','A counter is a cumulative amount. Subtract two timestamped readings, account for resets, and multiply byte delta by 8 before dividing by seconds.'),cmd('Get-NetAdapter | Select-Object Name, Status, LinkSpeed','Read the adapter’s reported link capability/state.','LinkSpeed is not an end-to-end speed test; virtual interfaces may report a nominal value.','Windows 11 / PowerShell')],
configuration:'Document the contracted rate and the application completion objective before adjusting QoS, shaping or transport buffers. A shaper and a policer behave differently: one can delay traffic while another may drop or remark excess. Validate policy against actual bottlenecks and preserve the previous profile for rollback. Do not increase load or kernel buffers across a fleet based on a single synthetic number.',
ports:'Bandwidth has no port number. TCP/UDP application tests use their own endpoints and must be authorized. This lab uses arithmetic and read-only counters rather than opening a traffic-generator listener or saturating a shared circuit.',
production:'A backup window is planned from useful data volume, measured goodput and competing business traffic. Engineers compare results with CPU/storage metrics and observe interactive latency during the backup. A successful bulk transfer that degrades business transactions can still fail the service objective.',
troubleshooting:[['Symptom','A new 1 Gb/s interface does not improve a remote backup rate.'],['Hypotheses','WAN rate limit, endpoint storage/CPU, loss, TCP window/RTT or backup compression behavior.'],['Test','Compare the full path capacity and simultaneous endpoint metrics; measure useful bytes over a stable interval.'],['Observation','Synthetic case: branch service is 100 Mb/s, near capacity during backup, while local disks and the upgraded NIC have headroom.'],['Conclusion / next test','The access NIC upgrade did not change the WAN bottleneck. Check contention and the required backup window before planning another upgrade.'],['Fix and verify','Choose an approved capacity, scheduling or application change. Verify completion time and latency of competing services under comparable load, with rollback criteria.']],
security:'Unbounded throughput tests can resemble denial of service and expose test listeners. Prefer existing authorized telemetry and a planned test window. Keep credentials and private filenames out of reports; throughput evidence rarely requires recording application payload.',
performance:'Capacity and RTT interact but are not interchangeable. More bandwidth reduces serialization time and can reduce congestion when it removes a bottleneck. It does not directly reduce propagation distance, database work or every handshake. Parallel streams can obscure a single-flow problem, so state stream count when reporting results.',
mistakes:['Confusing Mb/s and MB/s.','Reading a byte counter as a rate without an interval.','Treating BDP as a promised throughput or universal buffer setting.'],interactive:'link-budget',
lab:{objective:'Calculate capacity bounds, serialization and flight size with explicit units.',requirements:'Browser link calculator and notebook; no traffic-generator server.',topology:['Application bytes','Transport/IP overhead','Bottleneck link','Receiver'],steps:['Convert 100 Mb/s to decimal MB/s and estimate the ideal time for 125 MB.','Set link rate 100 Mb/s and the calculator’s 1500-byte outer IP example. Record its serialization time excluding link overhead.','Change rate to 1000 Mb/s while keeping RTT 40 ms. Compare serialization with the unchanged RTT input.','At 100 Mb/s and 40 ms, record the model BDP of 500,000 bytes. Explain why this is a flight-size estimate.','Synthetic counter exercise: 10,000,000 new bytes over 2 seconds equals 40,000,000 bits/s. List why this may differ from useful backup goodput.'],verification:'Results include 12.5 MB/s, 10 seconds ideal transfer, 0.12 ms IP serialization at 100 Mb/s, 0.012 ms at 1 Gb/s and 500,000 bytes BDP for 100 Mb/s × 40 ms.',troubleshooting:'The calculator does not model congestion control, overhead efficiency, storage, startup or retransmissions. Real measured rates need a stated layer and interval.',challenge:'A 64 KiB unscaled flight limit over 40 ms suggests what ideal window-limited rate? About 13.1 Mb/s before other constraints; do not assume modern TCP actually uses this fixed limit.',cleanup:'Reset the calculator. No traffic generator, listener or rate policy was created.'},
quick:[q('Beginner','Units','How many bits are in one byte?','Eight.','Use the factor before comparing Mb/s with MB/s.'),q('Intermediate','Measurement','Is a link-speed label an application goodput measurement?','No.','It describes a link property, not end-to-end useful delivery.'),q('Intermediate','Delay','Does increasing bandwidth necessarily lower propagation delay?','No.','Distance and signal propagation are separate from serialization.')],
exams:[q('Beginner','Conversion','100 Mb/s equals how many decimal MB/s before overhead?','12.5 MB/s.','Divide by eight.',['100 MB/s','800 MB/s','12.5 MB/s.','1.25 MB/s']),q('Intermediate','Transfer','What is the ideal payload time for 125 MB at 100 Mb/s?','10 seconds.','125 × 8 / 100 = 10; actual completion can take longer.'),q('Troubleshooting','Counters','An interface adds 10 MB in 2 seconds. What is the decimal rate?','40 Mb/s.','10,000,000 × 8 / 2 = 40,000,000 bits/s.',['5 Mb/s','40 Mb/s.','80 MB/s','160 Mb/s']),q('Intermediate','Goodput','Why can interface throughput exceed useful application goodput?','Headers, control traffic and retransmissions may be counted at the interface.','The measurement boundaries differ.'),q('Advanced','BDP','What is the BDP of 100 Mb/s and 40 ms RTT?','500,000 bytes.','100,000,000 × 0.04 / 8 = 500,000.'),q('Troubleshooting','Bottleneck','Why can upgrading a LAN NIC fail to improve a WAN backup?','The WAN or another path/endpoint resource may still be the bottleneck.','Capacity must be evaluated across the entire service path.'),q('Design','Testing','Why report test stream count and duration?','Parallelism and startup behavior affect measured rate and can hide single-flow constraints.','Reproducible performance evidence needs test conditions.'),q('Advanced','Window','Does a BDP estimate alone justify a global buffer increase?','No; measure actual transport, endpoint and workload constraints first.','Buffers, congestion control and application behavior interact.'),q('Security','Load','Why avoid an unbounded speed test on a shared production link?','It can consume service capacity and degrade other users.','Use authorized bounded tests and monitor competing services.'),q('Design','Acceptance','What should be checked alongside backup completion time?','Interactive service latency, loss and resource contention under the same workload.','Bulk goodput alone can hide a harmful tradeoff.')],
glossary:{Bandwidth:'Capacity expressed as bits per second in this context.',Throughput:'Achieved rate at a stated measurement boundary.',Goodput:'Useful application data delivered per unit time.',BDP:'Bandwidth-delay product estimating data in flight.'},related:['s0-g2-t1','s0-g2-t7','s0-g2-t9','s0-g2-t10'],sources:[refs.tcp,refs.link,refs.win,source('RFC 5136: network capacity definitions','https://www.rfc-editor.org/rfc/rfc5136')]
}),lesson(9,{
title:'Latency',subtitle:'Measure delay at the boundary the user actually experiences.',
definition:'Latency is elapsed delay for a specified operation or path. Network measurements may describe one-way delay or round-trip time; application latency also includes protocol exchanges and server work. A number is incomplete without endpoints, direction, packet/workload type and measurement conditions.',
purpose:'Interactive systems can feel slow even when they transfer little data. Delay measurements help distinguish propagation, serialization, queueing and processing, then connect those causes to user transactions. A capacity-only dashboard can miss severe queueing or slow application dependencies.',
mental:'A short letter can take a long trip even if the truck has room for thousands of letters. Waiting at loading points adds variable delay. The analogy stops at protocols: an application may wait for several sequential replies, and the request and response can travel along different paths.',
components:['Propagation: time for signals to travel across distance and media.','Serialization: time to place the chosen unit’s bits onto a link, calculated as bits/rate.','Queueing: waiting behind other traffic or work; often varies with load.','Processing: work in endpoints and forwarding devices.','Transaction dependencies: DNS, connection establishment, authentication and application/database work can add exchanges.'],
mechanism:['Define when the clock starts and stops. A ping reports an ICMP round trip plus relevant endpoint handling; it is not a direct one-way measurement. Dividing RTT by two assumes a symmetry that may not exist.','For a fixed packet size, serialization decreases as link rate rises. Propagation does not disappear when capacity rises. A 1500-byte IP packet needs 0.12 ms of IP-bit serialization at 100 Mb/s, excluding link overhead, regardless of whether a distant path adds tens of milliseconds.','Queueing grows when work arrives faster than a resource can serve it. Burst traffic can create delay even when a long-term average looks moderate. Large buffers can absorb bursts but may also retain traffic long enough to harm interactive use.','An application may require several sequential exchanges and processing steps. Tail latency reveals slow experiences hidden by an average. Compare time-series distributions, loss and workload context; a single high ICMP reply can reflect probe handling rather than all forwarded application traffic.'],
flow:[['Define timing','Choose endpoints, packet/workload type and start/stop events.'],['Traverse and wait','Serialization, propagation, queues and processing add delay.'],['Return or complete','RTT includes both paths; a transaction may require more exchanges.'],['Compare under load','Use distributions and comparable workloads to locate the changing component.']],
comparison:[['One-way delay','Source-to-destination time','Requires appropriate synchronized measurement or another valid method.'],['RTT','Request-to-reply elapsed time','Combines both paths and responder behavior.'],['Jitter / delay variation','Changes in delay between observations','Important for real-time applications; define the metric.'],['Application latency','Time for a defined user operation','Includes network and application dependencies.']],
example:'A backup changes the branch’s small-probe RTT from 20 ms idle to 250 ms under load, while the route and link rate stay the same. Queueing at the shared bottleneck is a plausible hypothesis. The engineer compares application latency and edge queues before changing QoS; a slower server could produce a superficially similar complaint.',
commands:[cmd('ping -c 5 127.0.0.1','Collect a small bounded sample of local ICMP round trips.','This is a command/summary exercise, not a WAN benchmark. Min/average/max summarize only five local probes; no physical path or Internet latency is measured.','Ubuntu 24.04 / Bash + iputils'),cmd('ip -s link show','Read interface traffic/error counters to correlate with an incident interval.','Counters alone do not identify queue delay or application processing. Combine them with relevant timing and workload evidence.')],
configuration:'Before tuning queues or QoS, identify the actual bottleneck and latency objective. Change one scoped policy with comparable before/after traffic and explicit rollback. Application placement, fewer serial dependencies or caching may be more effective than a link-rate change. Retain monitoring for both latency and loss so a queue adjustment does not merely trade excessive delay for unacceptable drops.',
ports:'Latency has no port number. ICMP probes use protocol types/codes. TCP connect time, TLS handshake time and HTTP response time measure different stages; a healthy ping does not establish healthy application latency.',
production:'Service owners define a transaction and target distribution, such as a percentile over an interval, then monitor network and server spans that explain it. Clocks and sampling need care when correlating events across systems. Rare slow requests can dominate user experience even if average latency remains attractive.',
troubleshooting:[['Symptom','Voice and interactive requests slow sharply during backups.'],['Hypotheses','Shared-edge queueing, server resource contention, loss recovery or a path change.'],['Test','Compare idle/loaded RTT, application timing, edge queue metrics and endpoint resource use over the same interval.'],['Observation','Synthetic record: route unchanged, server healthy, queue occupancy rises at the 100 Mb/s branch egress and both probes and calls slow.'],['Conclusion / next test','Queueing at the shared egress is supported. Check whether the policy/rate reflects the provider bottleneck.'],['Fix and verify','Apply the approved scheduling/shaping or workload schedule change. Recheck tail latency, packet loss and backup completion; revert if service objectives are not met.']],
security:'Keep probes bounded and directed to authorized endpoints. Timing data and packet traces can expose infrastructure layout; share sanitized measurements. Do not weaken authentication or encryption simply to reduce measured delay without analyzing the real cost and security requirements.',
performance:'Serialization, propagation and queueing respond to different interventions. More capacity may drain a congested queue but cannot eliminate remote processing or geographic distance. An average can hide a long tail; report suitable percentiles with sample size and period, and avoid treating a five-probe sample as a stable service percentile.',
mistakes:['Reporting ping RTT as one-way delay.','Using average latency alone for an interactive service.','Assuming bandwidth and latency are inverses in every situation.'],interactive:'link-budget',
lab:{objective:'Distinguish serialization changes from RTT and diagnose load-dependent delay.',requirements:'Link calculator and supplied synthetic timing record; optional local ping.',topology:['Client timing','Branch queue','WAN path','Responder timing'],steps:['Set rate 100 Mb/s and outer IP size 1500 bytes; record 0.12 ms serialization and RTT input 40 ms.','Raise the rate to 1000 Mb/s. Observe that serialization falls to 0.012 ms while the independent RTT input remains 40 ms.','Add 200 ms of model queue delay and record the one-way subtotal defined by the calculator; explain its exclusions.','Analyze the 20 → 250 ms backup scenario using the synthetic queue evidence above.','Write two separate claims: what a local five-probe ping actually tests, and what a representative application measurement would need.'],verification:'The report separates RTT from one-way subtotal, changes serialization with rate, and does not claim that the model measured a real path or that half-RTT is a known one-way delay.',troubleshooting:'The calculator treats propagation and queueing as independent inputs, omits processing, and models one serialization event. It is not a complete network simulation.',challenge:'An API makes five strictly sequential remote exchanges at 40 ms RTT before server work. Estimate the RTT contribution as about 200 ms under the stated assumptions; discuss connection reuse and parallelism.',cleanup:'Reset the calculator. The optional ping is local and bounded; no QoS or route change occurred.'},
quick:[q('Beginner','Direction','Is RTT the same as one-way delay?','No.','It includes request and return paths plus relevant handling.'),q('Intermediate','Cause','Does higher bandwidth eliminate propagation delay?','No.','Signal travel distance remains.'),q('Intermediate','Distribution','Can a good average hide very slow requests?','Yes.','The tail and sample context matter.')],
exams:[q('Beginner','RTT','What does a round-trip measurement include?','The outgoing and returning paths plus applicable endpoint handling.','It is broader than one-way transport.',['Only the first cable','The outgoing and returning paths plus applicable endpoint handling.','Only server CPU','Only packet size']),q('Intermediate','Serialization','What is the IP-only serialization time for 1500 bytes at 100 Mb/s?','0.12 ms.','1500 × 8 / 100,000,000 seconds = 0.00012 seconds.',['12 ms','1.2 ms','0.12 ms.','120 ms']),q('Troubleshooting','Load','RTT rises during backups with stable routing and increasing edge queue occupancy. What is supported?','Shared-bottleneck queueing is a plausible cause worth a scoped test.','The observations narrow the hypothesis but do not justify arbitrary policy changes.'),q('Advanced','Asymmetry','Why is RTT/2 not a reliable one-way measurement?','Forward and return paths, queues and handling may be unequal.','Symmetry is an assumption, not something the division proves.'),q('Design','Tail','Why monitor a latency distribution rather than only the mean?','A small fraction of very slow operations can harm users while the mean remains low.','Percentile interpretation still requires enough samples and a defined interval.'),q('Intermediate','Propagation','Which delay component is least directly changed by upgrading the same route’s link rate?','Propagation along that route.','Rate changes serialization and potentially queues, not physical distance.'),q('Advanced','Dependencies','Five sequential exchanges each require 40 ms RTT. What is their RTT-only contribution?','About 200 ms under the stated sequential assumptions.','Parallelism, reuse and processing change actual transaction time.'),q('Troubleshooting','Probe type','Why compare ICMP and application timing?','They can traverse different handling/policy and measure different work.','One probe type cannot fully describe every application.'),q('Design','Queues','What should be measured after reducing queue delay?','Loss, tail latency and workload completion, including competing services.','A change may trade waiting for drops.'),q('Security','Tuning','Why is disabling encryption a poor first latency intervention?','It changes the security boundary without establishing that cryptographic processing is the actual bottleneck.','Measure causes and meet both service and security requirements.')],
glossary:{Latency:'Elapsed delay for a specified operation or path.',RTT:'Round-trip time.',Serialization:'Time to place a unit’s bits onto a link.','Queueing delay':'Time waiting for a resource to serve the unit.'},related:['s0-g2-t1','s0-g2-t8','s0-g2-t10'],sources:[refs.tcp,refs.ping,source('RFC 2681: round-trip delay metric','https://www.rfc-editor.org/rfc/rfc2681')]
}),lesson(10,{
title:'Duplex',subtitle:'Check both link partners before interpreting collision counters.',
definition:'Duplex describes whether communication on a link can occur in both directions simultaneously. Full duplex supports simultaneous sending and receiving; half duplex shares transmission opportunities between directions. Modern switched Ethernet normally operates full duplex, while classic shared Ethernet used half-duplex collision handling.',
purpose:'Both ends must agree on the link’s operating behavior. Understanding duplex explains an important legacy failure pattern where link lights look healthy and small probes pass, yet loaded transfers perform badly. It also prevents the mistake of calling wireless contention identical to a dedicated full-duplex Ethernet port.',
mental:'A full-duplex link resembles separate lanes in both directions; a half-duplex link resembles a shared passage requiring coordination. This is only a directionality model: packet scheduling, radio multi-user features and hardware capabilities determine actual performance, not the lane analogy alone.',
components:['Two link partners: NIC/switch or switch/switch, each with configured and operational state.','Auto-negotiation: supported technologies exchange applicable capabilities; actual rules depend on the PHY.','Legacy collision domain: shared half-duplex Ethernet uses CSMA/CD behavior.','Counters and workload: late collisions, receive errors, throughput and direction help diagnose mismatch.','Technology limits: many modern Ethernet modes are full-duplex-only; legacy fallback examples must be scoped.'],
mechanism:['On compatible links using negotiation, both ends establish supported operating parameters. Read operational state at both endpoints rather than inferring it from the local desired configuration. A virtual NIC may not expose meaningful physical negotiation.','A classic 10/100 mismatch occurs when one end is forced to full duplex while the other uses auto. The auto side may detect speed by parallel detection but cannot learn duplex from a non-negotiating partner, leading to half-duplex fallback in that legacy case. This is not a universal rule for all Ethernet rates.','The half-duplex side observes contention according to its rules while the full-duplex side transmits without that collision discipline. Light traffic can appear usable; simultaneous load exposes errors, retransmissions and poor throughput. Late collisions are especially informative in the relevant legacy context but still require correlation.','Full-duplex Ethernet does not use CSMA/CD collision handling on that link. A collision counter on a supposedly full-duplex modern link may be unsupported, stale or require platform-specific interpretation. Do not force every modern port to a legacy fixed setting based on an old troubleshooting example.'],
flow:[['Read both sides','Capture configured and negotiated speed/duplex for each partner.'],['Check technology','Determine whether the legacy half-duplex/parallel-detection case even applies.'],['Correlate load','Compare error deltas and bidirectional behavior during a bounded test.'],['Align and verify','Use a supported consistent policy and validate service after the approved change.']],
comparison:[['Full duplex','Send and receive simultaneously','Dedicated link directions; no normal CSMA/CD collision operation.'],['Half duplex','Directions share transmission opportunities','Classic shared Ethernet needs contention handling.'],['Duplex mismatch','Partners use incompatible directionality','May fail mainly under simultaneous traffic.'],['WLAN airtime','Radio access contention and scheduling','Do not equate AP PHY rate with dedicated full-duplex Ethernet capacity.']],
example:'A legacy 100 Mb/s appliance is forced to full duplex while its switch port remains auto. The switch shows 100/half and rising late collisions under load. This is a teaching case for that legacy link; it is not an instruction to disable negotiation on gigabit or faster links.',
commands:[cmd('ethtool eth0','Read the operational speed, duplex, auto-negotiation and advertised capabilities where supported.','Use the actual interface name and inspect the partner separately. A virtual NIC may return unknown or synthetic data.','Linux / ethtool, optional physical NIC'),cmd('ip -s link show','Read generic error/collision counters for correlation.','Counter availability and semantics depend on the driver. A lifetime collision total without time, duplex and media context is not a diagnosis.')],
configuration:'Prefer the platform-supported negotiation policy on both ends. If a documented legacy exception requires fixed settings, coordinate compatible values at both partners in an approved window and retain the old settings. A remote speed/duplex change can sever management, so arrange console access. Verify operational state, error deltas and bidirectional service afterward.',
ports:'Duplex is a link property and has no TCP/UDP port. The phrase “switch port duplex” refers to a physical/interface setting, not a transport service port.',
production:'Operations standards document supported media and negotiation policies, flag exceptions and preserve partner mapping. A duplex incident report includes both endpoint outputs, software/driver context, workload direction and timestamped error deltas. Replacement appliances should be tested under simultaneous traffic before assuming compatibility from link-up alone.',
troubleshooting:[['Symptom','A legacy appliance pings successfully but file transfers collapse under simultaneous traffic.'],['Hypotheses','Duplex mismatch, damaged medium, congestion or endpoint resource limits.'],['Test','Read both partners and compare error deltas during a bounded workload.'],['Observation','Synthetic record: appliance 100/full forced, switch 100/half auto, late collisions increase on the half side.'],['Conclusion / next test','The operating mismatch and load-correlated errors support the legacy negotiation hypothesis. Confirm supported settings for the appliance before changing either side.'],['Fix and verify','Align both ends using a supported policy, then confirm operational match, clean new error counts and expected bidirectional service. Restore previous settings if the link cannot be recovered through the planned path.']],
security:'Changing link parameters can disrupt every flow on that interface, including management and monitoring. Restrict configuration rights and maintain out-of-band recovery. Do not bypass access controls just to run a throughput test; use approved endpoints and a bounded load.',
performance:'A 1 Gb/s full-duplex link can carry nominal 1 Gb/s in each direction simultaneously, but one unidirectional flow does not become 2 Gb/s. Overhead, endpoint limits and shared uplinks still apply. A mismatch creates loss/recovery effects that can reduce useful throughput far below the nominal rate.',
mistakes:['Treating successful ping as proof of duplex agreement.','Adding both directions and promising 2 Gb/s to one flow on 1 Gb/s Ethernet.','Applying classic 10/100 parallel-detection advice to every modern PHY.'],
lab:{objective:'Diagnose a legacy mismatch from both partners while respecting technology scope.',requirements:'Notebook and synthetic endpoint/counter record. Optional read-only ethtool if a physical Linux NIC exists.',topology:['Appliance 100/full forced','Legacy Ethernet link','Switch 100/half auto'],steps:['Write the configured and observed state of each partner from the supplied scenario.','Predict why a few small pings can pass despite the disagreement.','Correlate rising late collisions with the half-duplex side and simultaneous load.','Write a supported-policy correction and recovery plan, without changing any NIC or switch.','For a separate 1 Gb/s full-duplex link, calculate the nominal maximum per direction and explain why a single one-way flow remains bounded to 1 Gb/s before overhead.'],verification:'The diagnosis uses both partners, workload and counter deltas, scopes fallback to the legacy example, and distinguishes per-direction from aggregate capacity.',troubleshooting:'Unknown duplex in a VM or WSL is a visibility limitation. Do not manufacture a physical diagnosis from a virtual interface’s nominal properties.',challenge:'If both endpoints already show matching full duplex and no relevant new errors, what other evidence would you collect for a slow transfer?',cleanup:'No link setting or traffic generator was changed. Retain the tabletop correction plan.'},
quick:[q('Beginner','Directions','Can a full-duplex link send and receive at once?','Yes.','Both directions can operate simultaneously.'),q('Intermediate','Scope','Does classic 10/100 auto fallback describe every modern PHY?','No.','Negotiation behavior and supported modes are technology-specific.'),q('Intermediate','Capacity','Does 1 Gb/s full duplex promise 2 Gb/s for one one-way flow?','No.','Nominal capacity is 1 Gb/s in each direction.')],
exams:[q('Beginner','Definition','What is full duplex?','Simultaneous sending and receiving on the link.','It is a directionality property, not a doubled one-way payload rate.',['Only sending','Alternating directions only','Simultaneous sending and receiving on the link.','An IP routing mode']),q('Intermediate','Legacy negotiation','In the stated legacy 10/100 example, why can the auto side choose half duplex?','It can detect speed without learning duplex from the forced non-negotiating partner.','The example is scoped to legacy parallel-detection behavior.'),q('Troubleshooting','Evidence','Which combination best supports the lesson’s mismatch diagnosis?','Different operational duplex at partners plus load-correlated late collisions.','Link-up or low throughput alone has many possible causes.',['Only one successful ping','Different operational duplex at partners plus load-correlated late collisions.','A DNS timeout alone','A large disk']),q('Intermediate','Capacity','What is the nominal directional rate of a 1 Gb/s full-duplex link?','1 Gb/s each way simultaneously.','A single direction does not gain the sum of both directions.'),q('Advanced','Collisions','Does normal full-duplex Ethernet use CSMA/CD collisions to share the link?','No.','Classic half-duplex shared Ethernet has that collision behavior.'),q('Troubleshooting','Probe','Why can ping pass during a duplex mismatch?','A small/light exchange may avoid the simultaneous load that exposes the problem.','A successful probe is a limited workload test.'),q('Design','Change','Why coordinate both partners and retain console access before correcting duplex?','Inconsistent settings or a link reset can sever traffic and remote management.','The repair must have a supported configuration and recovery path.'),q('Advanced','Virtualization','What does unknown duplex on a virtual NIC establish?','A limitation of exposed virtual/driver information, not a proven physical mismatch.','Inspect the actual physical host/link when that evidence is needed.'),q('Troubleshooting','Alternative','Both ends match full duplex with clean new counters, but transfer is slow. What next?','Investigate bottleneck capacity, loss elsewhere, endpoint resources and transport/application behavior.','Do not continue forcing duplex after evidence points elsewhere.'),q('Design','Modern links','Why avoid blanket forced speed/duplex policy copied from an old guide?','Modern PHYs have different negotiation requirements and supported modes.','Use current platform-specific supported behavior and verify both ends.')],
glossary:{Duplex:'Whether directions can operate simultaneously.','Full duplex':'Simultaneous transmission and reception.','Half duplex':'Shared/alternating transmission opportunities.','Auto-negotiation':'Exchange of applicable supported link capabilities.'},related:['s0-g2-t2','s0-g2-t3','s0-g2-t8','s0-g2-t9'],sources:[refs.duplex,refs.tool,refs.link]
}));
lessons[1].sources.push(source('Cisco: wide area networks','https://www.cisco.com/site/us/en/learn/topics/networking/what-is-a-wan-wide-area-network.html'));
lessons[2].sources.push(source('Microsoft: netsh wlan inspection commands','https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/netsh-wlan'));
lessons[7].sources.push(source('RFC 8201: IPv6 Path MTU Discovery','https://www.rfc-editor.org/rfc/rfc8201'));
lessons.forEach(l=>{l.exams.forEach((x,i)=>Object.assign(x,{topicId:l.id,questionId:`${l.id}-Q${String(i+1).padStart(2,'0')}`}));l.quick.forEach((x,i)=>Object.assign(x,{topicId:l.id,questionId:`${l.id}-QC${i+1}`}));});
window.INFRA_BATCHES=window.INFRA_BATCHES||{};window.INFRA_BATCHES['03']=lessons;
})();
